// ===== 13-grand: the GRAND CAMPAIGN (Abdullah 2026-11-05 19:16: "this entire game is just one layer") =====
// A Total War / EU4-style world map over the RTS: provinces, armies, simultaneous turns, tax, supply. Battles are fought
// live ("Fight it": a Conquest battle that holds EXACTLY the armies' real units, see 13b-grandui.js + grandBattleSetup in
// 03-sim) or auto-resolved. Everything in this file is deterministic from (state, orders, seed): no Math.random, no
// Date, so the same seed gives the same game and friends-multiplayer (stage 7) can be added without a rewrite.
// Design + stage plan: orch/reports/grand-strategy.md. Map data: 13-grandmap.js (generated by orch/grandmap-gen.mjs).
const GR_KEY='ww3grand1';
let GC=null;                       // the campaign state (JSON-safe; this is what is saved)
let GCM=null;                      // the static map (built once from GM_P)
const GR_TAX=['Low','Normal','High'],GR_TAXK=[.55,1,1.6],GR_TAXU=[-9,0,24];
const GR_PROXY={NA:['US'],SAM:['US'],EU:['DE','FR','EU','US'],ME:['SA','EG'],AF:['EG','SA'],SA:['IN','PK'],EA:['CN','KR'],SEA:['CN','KR'],OC:['US']};
const GR_REGIONS=[['World',null],['North America',[20,60,700,560]],['South America',[250,600,420,560]],['Europe & Russia',[800,40,720,470]],['Middle East & N. Africa',[1050,330,620,470]],['South Asia',[1380,380,440,380]],['East Asia',[1800,240,520,420]],['Africa',[820,620,500,560]],['SE Asia & Oceania',[1760,600,600,560]]];
const GR_MIX=[['inf',.46],['at',.14],['tank',.16],['arty',.08],['aa',.06],['heli',.05],['drone',.04]];
const GR_RECRUIT=[['inf',4,1],['at',2,1],['tank',2,2],['arty',2,2],['aa',2,1],['heli',1,2],['drone',3,1]];   // kind, batch size, turns to arrive
const GR_HOLY=new Set(['Najaf']);   // provinces with a holy city (RV Call to the Shrines)
const GR_VBASE=42000;              // start strength (unit value) of every full nation - same for all (Abdullah: all nations equally strong)
function grRng(s){return mulberry((s|0)^0x5bd1e995);}
function grHash(){if(!GC)return '';let s=GC.turn+'|'+GC.seed;for(const c of Object.keys(GC.nat).sort()){const n=GC.nat[c];s+='|'+c+':'+Math.round(n.cash)+','+n.cap+','+(n.dead?1:0);}
  for(const p of GC.prov)s+='|'+p.o+','+Math.round(p.un)+','+p.tax+','+p.gar.length+','+p.gar.reduce((a,r)=>a+r[1],0);
  for(const a of GC.armies)s+='|'+a.id+a.o+'@'+a.at+','+a.u.length+','+a.u.reduce((q,r)=>q+r[1]+r[2],0);
  s+='|W'+Object.keys(GC.war).sort().join(',');try{s+=geHashStr();}catch(e){}try{s+=gmilHashStr();}catch(e){}let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}

// ---------- static map ----------
// Real capital city of every nation (seat of government; source list in orch/REAL-2026.md). Shown on the capital's name plate. The 13-grandmap.js nation table is generated,
// so the names live here. No entry = the plate keeps the province name (IL: left to the owner; BI: fictional).
const GR_CAPCITY="US Washington;CA Ottawa;MX Mexico City;CU Havana;GT Guatemala City;DO Santo Domingo;VE Caracas;CO Bogotá;BR Brasília;PE Lima;AR Buenos Aires;CL Santiago;GB London;FR Paris;DE Berlin;ES Madrid;IT Rome;PL Warsaw;SE Stockholm;NO Oslo;FI Helsinki;GR Athens;RO Bucharest;BY Minsk;UA Kyiv;RU Moscow;KZ Astana;UZ Tashkent;AZ Baku;TR Ankara;SY Damascus;RS Beirut;JO Amman;IQ Baghdad;KD Erbil;RV Najaf;OB Gaza;IR Tehran;SA Riyadh;AE Abu Dhabi;OM Muscat;KW Kuwait City;QA Doha;DW Sanaa;EG Cairo;LY Tripoli;SD Khartoum;ET Addis Ababa;DZ Algiers;MA Rabat;TN Tunis;NG Abuja;ML Bamako;TD N'Djamena;CD Kinshasa;KE Nairobi;TZ Dodoma;AO Luanda;ZA Pretoria;PK Islamabad;IN New Delhi;AF Kabul;BD Dhaka;NP Kathmandu;LK Colombo;MM Naypyidaw;TM Ashgabat;CN Beijing;KP Pyongyang;KR Seoul;JP Tokyo;TW Taipei;MN Ulaanbaatar;VN Hanoi;TH Bangkok;MY Kuala Lumpur;ID Jakarta;PH Manila;AU Canberra;NZ Wellington;AL Tirana;AM Yerevan;AT Vienna;BA Sarajevo;BE Brussels;BG Sofia;BH Manama;BJ Porto-Novo;BN Bandar Seri Begawan;BO La Paz;BT Thimphu;BW Gaborone;CF Bangui;CG Brazzaville;CH Bern;CI Yamoussoukro;CK Avarua;CM Yaoundé;CV Praia;CY Nicosia;CZ Prague;DJ Djibouti;DK Copenhagen;EC Quito;EE Tallinn;ER Asmara;FJ Suva;FM Palikir;GA Libreville;GE Tbilisi;GH Accra;GM Banjul;GN Conakry;GQ Malabo;GS King Edward Point;GW Bissau;GY Georgetown;HR Zagreb;HU Budapest;IE Dublin;IS Reykjavik;KG Bishkek;KH Phnom Penh;KI Tarawa;KM Moroni;LA Vientiane;LR Monrovia;LS Maseru;LT Vilnius;LU Luxembourg;LV Riga;MD Chișinău;ME Podgorica;MG Antananarivo;MH Majuro;MK Skopje;MP Saipan;MR Nouakchott;MT Valletta;MU Port Louis;MV Malé;MW Lilongwe;MZ Maputo;NA Windhoek;NL Amsterdam;PG Port Moresby;PS Ramallah;PT Lisbon;PW Ngerulmud;PY Asunción;RW Kigali;SB Honiara;SC Victoria;SG Singapore;SI Ljubljana;SK Bratislava;SL Freetown;SN Dakar;SO Mogadishu;SR Paramaribo;SS Juba;ST São Tomé;SZ Mbabane;TC Cockburn Town;TF Port-aux-Français;TG Lomé;TJ Dushanbe;TL Dili;TO Nuku'alofa;UG Kampala;UY Montevideo;VU Port Vila;WS Apia;XB Gitega;XK Pristina;XS Belgrade;ZM Lusaka;ZW Harare";
// capital provinces named after a different real city keep their own name on the plate (the real capital lies elsewhere on the map)
const GR_CAPKEEP=new Set(['TR','NG','ZA']);
function grCapName(pi){const p=GCM.P[pi],o=GC&&GC.prov[pi]?GC.prov[pi].o:p.o,n=GCM.nats.get(o);return n&&n.city&&p.o===o&&!GR_CAPKEEP.has(o)&&GC&&GC.nat[o]&&GC.nat[o].cap===pi?n.city:p.n;}
function grMap(){if(GCM)return GCM;const P=GM_P.map((r,i)=>({i,n:r[0],o:r[1],x:r[2],y:r[3],t:r[4],tw:r[5],fl:r[6]||'',map:r[7]||'',adj:r[8],sea:r[4]==='w',land:i<GM_LAND}));
  const rv=new Set(GM_RIVER.map(r=>r[0]*1000+r[1])),byName=new Map(P.map(p=>[p.n,p.i]));
  for(const p of P){if(p.sea){p.ck=p.fl==='K';p.cost=p.tw||1;p.dev=0;}else{p.cap=p.fl.includes('C');p.wg=p.fl.includes('W')||p.cap;p.port=p.fl.includes('P');p.oil=p.fl.includes('O');p.farm=p.fl.includes('F');p.mine=p.fl.includes('M');p.dev=p.tw+(p.oil?2:0)+(p.farm?1:0)+(p.mine?1:0)+(p.port?1:0);
    // a province touching an ocean sea zone with a port can embark; coastal = touches any sea zone
    p.coast=p.adj.some(j=>P[j].sea);}}
  GCM={P,rv,byName,nats:new Map(GM_NATS.map(r=>[r[0],{code:r[0],name:r[1],reg:r[2]}]))};GR_CAPCITY.split(';').forEach(r=>{const n=GCM.nats.get(r.slice(0,2));if(n)n.city=r.slice(3);});
  // regions for the quick-jump buttons: nearest region rectangle centre
  return GCM;}
function grRiver(a,b){return GCM.rv.has(Math.min(a,b)*1000+Math.max(a,b));}
function grNat(code){const n=GCM.nats.get(code)||{code,name:code,reg:'EU'};if(n.fac)return n;const major=!!FACTIONS[code]&&code!=='EU';let fac=code;
  if(!major){fac=(GR_PROXY[n.reg]||['US']).find(f=>FACTIONS[f])||'US';}
  n.major=major;n.fac=fac;Object.defineProperty(n,'color',{get(){return grPalette(GC&&GC.me).get(code)||'#8a8f86';},enumerable:true});return n;}
// ---------- political map colours (ONE table: map, mini-map, key, panels) ----------
// Every nation gets a calm land colour so that no two neighbours (shared land border, or facing each other across a narrow sea) look alike:
// CIE Lab distance >= GR_PAL_DE and never the same hue family. The player's nation keeps its identity colour, other full nations stay as
// near theirs as the rule allows, everyone else is spread out. Deterministic (static start borders); the real identity lives in the flags.
const GR_PAL_DE=28,GR_PAL_HUE=40;
function grLab(hex){let v=[1,3,5].map(i=>parseInt(hex.substr(i,2),16)/255).map(c=>c>.04045?Math.pow((c+.055)/1.055,2.4):c/12.92);
  const f=t=>t>.008856?Math.cbrt(t):7.787*t+16/116,x=f((.4124*v[0]+.3576*v[1]+.1805*v[2])/.95047),y=f(.2126*v[0]+.7152*v[1]+.0722*v[2]),z=f((.0193*v[0]+.1192*v[1]+.9505*v[2])/1.08883);
  const L=116*y-16,a=500*(x-y),b=200*(y-z);return {L,a,b,C:Math.hypot(a,b),h:(Math.atan2(b,a)*180/Math.PI+360)%360};}
function grLch(L,C,h){const a=C*Math.cos(h*Math.PI/180),b=C*Math.sin(h*Math.PI/180),fy=(L+16)/116,fx=fy+a/500,fz=fy-b/200,g=t=>t*t*t>.008856?t*t*t:(t-16/116)/7.787,X=g(fx)*.95047,Y=g(fy),Z=g(fz)*1.08883;
  return '#'+[3.2406*X-1.5372*Y-.4986*Z,-.9689*X+1.8758*Y+.0415*Z,.0557*X-.204*Y+1.057*Z].map(c=>{c=c>.0031308?1.055*Math.pow(c,1/2.4)-.055:12.92*c;return Math.round(Math.max(0,Math.min(1,c))*255).toString(16).padStart(2,'0');}).join('');}
function grHex(c){if(/^#[0-9a-f]{6}$/i.test(c))return c;if(/^#[0-9a-f]{3}$/i.test(c))return '#'+c[1]+c[1]+c[2]+c[2]+c[3]+c[3];return '#808080';}
function grPalClash(A,B){if(Math.hypot(A.L-B.L,A.a-B.a,A.b-B.b)<GR_PAL_DE)return true;if(A.C<12&&B.C<12)return true;if(A.C<12||B.C<12)return false;const d=Math.abs(A.h-B.h);return Math.min(d,360-d)<GR_PAL_HUE;}
// who is next to whom at the start: land border, or both on the same sea zone and close (Gulf, Red Sea, straits), or simply very close (island states)
function grPalAdj(){grMap();if(GCM.padj)return GCM.padj;const P=GCM.P,A=new Map(),lk=(a,b)=>{if(a===b||!a||!b)return;(A.get(a)||A.set(a,new Set()).get(a)).add(b);(A.get(b)||A.set(b,new Set()).get(b)).add(a);};
  for(const r of GM_NATS)A.set(r[0],new Set());
  for(let i=0;i<GM_LAND;i++){const p=P[i];for(const j of p.adj){const q=P[j];if(q.sea){for(const k of q.adj){const s=P[k];if(k>i&&!s.sea&&s.o!==p.o&&Math.hypot(s.x-p.x,s.y-p.y)<45)lk(p.o,s.o);}}else if(j>i)lk(p.o,q.o);}
    for(let k=i+1;k<GM_LAND;k++){const s=P[k];if(s.o!==p.o&&Math.abs(s.x-p.x)<22&&Math.hypot(s.x-p.x,s.y-p.y)<22)lk(p.o,s.o);}}
  return GCM.padj=A;}
function grPalette(me){grMap();me=me||'';GCM.pal=GCM.pal||new Map();let M=GCM.pal.get(me);if(M)return M;M=new Map();const A=grPalAdj(),lab=new Map(),codes=GM_NATS.map(r=>r[0]),isM=c=>!!FACTIONS[c]&&c!=='EU';
  const calm=c=>{const l=grLab(grHex(FACTIONS[c].color));return grLch(Math.max(40,Math.min(74,l.L)),Math.min(44,l.C),l.h);};
  const cand=[];for(const L of [50,60,69,78])for(const C of [16,27,38])for(let h=(L*7+C)%20;h<360;h+=20){if((h>228&&h<292&&L<75)||(C>30&&L>72))continue;const x=grLch(L,C,h);cand.push([x,grLab(x)]);}   // no sea blues
  for(const L of [46,58,70,81]){const x=grLch(L,5,80);cand.push([x,grLab(x)]);}
  const ok=(c,l)=>{for(const n of A.get(c)||[]){const q=lab.get(n);if(q&&grPalClash(l,q))return false;}return true;};
  const minD=(c,l,two)=>{let d=999;for(const n of A.get(c)||[]){const q=lab.get(n);if(q)d=Math.min(d,Math.hypot(l.L-q.L,l.a-q.a,l.b-q.b));if(two)for(const m of A.get(n)||[]){const r=m!==c&&lab.get(m);if(r)d=Math.min(d,Math.hypot(l.L-r.L,l.a-r.a,l.b-r.b)+14);}}return d;};
  const put=(c,x)=>{M.set(c,x);lab.set(c,grLab(x));};
  const np={};for(let i=0;i<GM_LAND;i++)np[GCM.P[i].o]=(np[GCM.P[i].o]||0)+1;
  const order=codes.filter(isM).map((c,i)=>[c,i]).sort((a,b)=>(np[b[0]]||0)-(np[a[0]]||0)||a[1]-b[1]).map(r=>r[0]).concat(codes.filter(c=>!isM(c)).map((c,i)=>[c,i]).sort((a,b)=>(A.get(b[0])||[]).size-(A.get(a[0])||[]).size||a[1]-b[1]).map(r=>r[0]));
  if(me&&isM(me))put(me,calm(me));
  for(const c of order){if(M.has(c))continue;let best=null,bs=-1e9;
    if(isM(c)){const id=calm(c),il=grLab(id);if(ok(c,il)){put(c,id);continue;}
      for(const [x,l] of cand){if(!ok(c,l))continue;const s=-Math.hypot(l.L-il.L,l.a-il.a,l.b-il.b);if(s>bs){bs=s;best=x;}}}
    else{let hh=7;for(const ch of c)hh=hh*31+ch.charCodeAt(0)>>>0;cand.forEach(([x,l],k)=>{if(!ok(c,l))return;const s=Math.min(60,minD(c,l,true))+((hh+k*2654435761>>>0)%1000)/400;if(s>bs){bs=s;best=x;}});}
    if(!best)for(const [x,l] of cand){const s=minD(c,l,false);if(s>bs){bs=s;best=x;}}   // nothing fits every rule: the most different colour there is
    put(c,best);}
  // repair: a nation that still clashes (dense corners like the Balkans) is re-picked knowing all its neighbours; small nations first, never the player
  for(let rnd=0;rnd<8;rnd++){let left=0;for(const c of order.slice().reverse()){if(c===me||ok(c,lab.get(c)))continue;left++;const hit=cand.find(([x,l])=>ok(c,l));if(hit){put(c,hit[0]);continue;}
      for(const n of A.get(c)||[]){if(n===me||isM(n)&&rnd<4)continue;const alt=cand.find(([x,l])=>ok(n,l)&&!grPalClash(l,lab.get(c)));if(alt)put(n,alt[0]);}}if(!left)break;}
  GCM.pal.set(me,M);return M;}
// guard helper: neighbour pairs whose colours are too close for this player ([] = fine)
function grPaletteBad(me){const M=grPalette(me),A=grPalAdj(),bad=[];for(const [a,S] of A)for(const b of S)if(a<b&&grPalClash(grLab(M.get(a)),grLab(M.get(b))))bad.push(a+'-'+b);return bad;}
function grMajors(){grMap();return [...new Set(GM_P.slice(0,GM_LAND).map(r=>r[1]))].filter(c=>grNat(c).major);}

// ---------- units ----------
// A unit record is [kind, health %, experience, ammo %]. Armies and garrisons are arrays of them; a live battle spawns exactly
// these and writes every survivor back, so what you take into a battle is what comes out (minus the dead).
function grHasKind(fac,k){try{return !!stats(fac,k);}catch(e){return false;}}
function grCost(fac,k){try{return stats(fac,k).cost||400;}catch(e){return 400;}}
function grRankOf(k,fac,xp){const base=Math.max(300,grCost(fac,k));let r=0;const need=[1,2.5,5];while(r<3&&xp>=base*need[r])r++;return r;}
function grUnitVal(fac,r){return grCost(fac,r[0])*(.35+.65*r[1]/100)*(1+.15*grRankOf(r[0],fac,r[2]))*(.75+.25*r[3]/100);}
function grForce(fac,us){let v=0;for(const r of us)v+=grUnitVal(fac,r);return v;}
function grGenUnits(fac,value,gen){const us=[];const ks=GR_MIX.filter(m=>grHasKind(fac,m[0]));const tw=ks.reduce((a,m)=>a+m[1],0);
  for(const [k,w] of ks){const c=grCost(fac,k);let n=Math.round(value*w/tw/c);if(k==='inf')n=Math.max(n,2);for(let i=0;i<n;i++)us.push([k,100,0,100]);}
  if(gen&&grHasKind(fac,'champ'))us.push(['champ',100,0,100]);return us;}
function grKindName(fac,k){try{return stats(fac,k).name;}catch(e){return k;}}

// ---------- new campaign ----------
function grNew(o){GR_LASTB=null;grMap();const seed=(o.seed|0)||1,quick=o.len!=='std',R=grRng(seed);
  GC={v:1,ms:grMapSig(),seed,len:quick?'quick':'std',maxTurn:quick?25:60,turn:1,m0:(typeof GR_REAL==='object'&&GR_REAL.asof)?(GR_REAL.asof[0]-2026)*12+GR_REAL.asof[1]-1:10,me:o.me===undefined?'IR':o.me,nat:{},prov:[],armies:[],aid:1,war:{},log:[],q:[],qi:0,ph:'plan',over:null,res:null};
  const codes=[...new Set(GM_P.slice(0,GM_LAND).map(r=>r[1]))];
  GM_P.slice(0,GM_LAND).forEach((r,i)=>{GC.prov.push({o:r[1],o0:r[1],gar:[],tax:1,un:15,cv:0,rq:[]});});
  for(const c of codes){const N=grNat(c),ps=GCM.P.filter(p=>p.land&&GC.prov[p.i].o===c);const cap=ps.find(p=>p.cap)||ps[0];
    GC.nat[c]={code:c,cash:grRealCash(c,N.major?2200:900),cap:cap.i,wg:ps.filter(p=>p.wg).map(p=>p.i),dead:0,an:0,ai:c!==GC.me,home:ps.map(p=>p.i)};
    const V=GR_VBASE*grRealMil(c,N.major?1:.5)*(quick?.7:1),sd=ps.reduce((a,p)=>a+p.dev,0),fac=N.fac;
    for(const p of ps)GC.prov[p.i].gar=grGenUnits(fac,V*.5*p.dev/sd,false);
    const wgp=ps.find(p=>p.wg&&p.i!==cap.i);const capShare=wgp?.3:.5;
    grAddArmy(c,cap.i,grGenUnits(fac,V*capShare,true));if(wgp)grAddArmy(c,wgp.i,grGenUnits(fac,V*.2,false));}
  // opening wars: each region's majors fight in a ring (first and last of a pair only when the region has two or more), so every nation
  // starts with the same number of rivals; the player's nation always has at least one
  const byReg={};for(const c of grMajors()){const r=grNat(c).reg;(byReg[r]=byReg[r]||[]).push(c);}
  if(false)for(const r of Object.keys(byReg).sort()){const L=byReg[r].sort((a,b)=>GCM.P[GC.nat[a].cap].x-GCM.P[GC.nat[b].cap].x);if(L.length>=2)for(let i=0;i<L.length;i++){const a=L[i],b=L[(i+1)%L.length];if(a!==b)GC.war[grWk(a,b)]=1;}}
  if(GC.me&&!GR_REAL.wars.concat(GR_REAL.tn,GR_REAL.tr||[]).some(x=>x.includes(GC.me))&&!Object.keys(GC.war).some(k=>k.split('|').includes(GC.me))){let best=null,bd=1e9;for(const c of grMajors())if(c!==GC.me){const d=grDist(GC.nat[c].cap,GC.nat[GC.me].cap);if(d<bd){bd=d;best=c;}}if(best)GC.war[grWk(GC.me,best)]=1;}
  geEnsure();grRealApply(quick);GC.sc=GR_SCEN.some(x=>x.id===o.sc)?o.sc:'me26';grScenApply(GC.sc,quick);try{for(const c of Object.keys(GC.nat))gfInit(c);}catch(e){console.error('gfInit',e);}
  grLog('The campaign begins. '+(GC.me?GCM.nats.get(GC.me).name+' takes the field.':'Observer mode.'),GC.me);
  return GC;}
/* RG6 scenario starts (laneA 2026-11-07): each scenario is a preset ON TOP of the realistic start (grRealApply) — extra opening wars,
   opinions and front armies. Data rows only; deterministic (no RNG). 'me26' = the plain realistic start (featured: "Middle East 2026"). */
const GR_SCEN=[
 {id:'me26',n:'Middle East 2026',d:'The world as it stands in November 2026: Russia and Ukraine at war, Yemen and Saudi Arabia at war, Pakistan and Afghanistan at war; fragile ceasefires between Israel and the Lebanese Shia and between Iran and the US and Israel, with the Strait of Hormuz closed and oil above $100.'},
 {id:'gulf',n:'Gulf flashpoint',d:'Tankers burn in the Strait of Hormuz. Iran and its Resistance bloc are at war with Saudi Arabia and the UAE; the US is on the brink and Gulf neighbors pick sides.',
  wars:[['IR','SA'],['IR','AE'],['DW','SA'],['DW','AE']],op:[['US','IR',-100],['QA','IR',-40],['KW','IR',-40],['OM','IR',-5],['IQ','SA',-25]],
  fr:[['IR','SA',.25],['SA','IR',.25],['IR','AE',.15],['AE','IR',.2],['DW','SA',.2],['SA','DW',.15],['US','IR',.08]],
  news:['Tankers ablaze in the Strait of Hormuz — Iran and Saudi Arabia are at war.','The UAE closes its airspace; Yemen\'s Zaidi Shia Movement fire on Saudi border posts.']},
 {id:'redsea',n:'Red Sea crisis',d:'Shipping through Bab-el-Mandeb has stopped. Yemen\'s Zaidi Shia Movement are at war with Israel and Saudi Arabia; Egypt loses its canal trade and the Gulf watches.',
  wars:[['DW','IL'],['DW','SA']],op:[['EG','DW',-60],['US','DW',-100],['AE','DW',-50]],
  fr:[['DW','SA',.25],['SA','DW',.25],['EG','DW',.1]],
  news:['Ships turn back at Bab-el-Mandeb — the Red Sea is a war zone.','Suez traffic collapses; Cairo warns Sanaa.']}];
function grScenApply(id,quick){const S=GR_SCEN.find(x=>x.id===id);if(!S||!S.wars&&!S.op&&!S.fr)return;const has=c=>!!GC.nat[c]&&!GC.nat[c].dead;GC.rel=GC.rel||{};
  for(const [a,b,v] of S.op||[])if(has(a)&&has(b))GC.rel[grWk(a,b)]=v;
  for(const [a,b] of S.wars||[])if(has(a)&&has(b)){GC.war[grWk(a,b)]=1;GC.rel[grWk(a,b)]=-100;}
  for(const [a,b,sh] of S.fr||[])if(has(a)&&has(b)){const at=grNearOwn(a,GC.nat[b].cap);if(at<0)continue;const V=GR_VBASE*grRealMil(a,grNat(a).major?1:.5)*(quick?.7:1);grAddArmy(a,at,grGenUnits(grNat(a).fac,V*sh,false),'Front Army');}
  grLog('Scenario: '+S.n+'.',GC.me);for(const t of S.news||[])grLog(t,'');}
/* RG3 fog of war + spies (laneA 2026-11-07): what the PLAYER sees on the grand map. Display/UI only — the sim and the AI are unchanged,
   so it stays deterministic and identical for every player. You see armies of yourself and allies, and any army in or next to a
   province you or your allies hold or stand in; nations with spy satellites (GR_SAT) see two provinces deep; "Send spies" on an
   enemy province reveals all that nation's armies for GR_SPY_M months. */
const GR_SAT=['US','CN','RU','IL','IN','FR','GB','JP'],GR_SPY_COST=400,GR_SPY_M=3;let GR_SEEN=null;
function grFriend(a,b){return a===b||(typeof grAllied==='function'&&grAllied(a,b));}
function grSeenSet(){if(!GC||!GC.me)return null;let sig=GC.turn*31+(GC.day|0);for(const a of GC.armies)sig=(sig*7+a.at*13+a.id)%1000000007;const k=GC.me+'|'+sig+'|'+GC.armies.length;
  if(GR_SEEN&&GR_SEEN.k===k)return GR_SEEN.s;const me=GC.me,fr={},s=new Set(),seed=[];const F=c=>fr[c]!==undefined?fr[c]:(fr[c]=grFriend(me,c));
  for(const p of GCM.P)if(p.land&&F(GC.prov[p.i].o))seed.push(p.i);for(const a of GC.armies)if(F(a.o))seed.push(a.at);
  const deep=GR_SAT.includes(me)?2:1;let ring=seed;for(const i of seed)s.add(i);for(let d=0;d<deep;d++){const nx=[];for(const i of ring)for(const j of GCM.P[i].adj||[])if(!s.has(j)){s.add(j);nx.push(j);}ring=nx;}
  GR_SEEN={k,s};return s;}
function grSeen(a){if(!GC||!GC.me||!a)return true;if(grFriend(GC.me,a.o))return true;if(GC.spy&&(GC.spy[GC.me+'>'+a.o]|0)>=GC.turn)return true;const s=grSeenSet();return !s||s.has(a.at);}
function grSpy(me,t){const N=GC.nat[me];if(!N||!GC.nat[t]||grFriend(me,t))return 'Not an enemy';if(N.cash<GR_SPY_COST)return 'Needs $'+GR_SPY_COST;GC.spy=GC.spy||{};if((GC.spy[me+'>'+t]|0)>=GC.turn)return 'Spies already there';
  N.cash-=GR_SPY_COST;GC.spy[me+'>'+t]=GC.turn+GR_SPY_M-1;GR_SEEN=null;grLog('Our spies are inside '+GCM.nats.get(t).name+' — all their armies are on our maps until '+grMonStr(GC.turn+GR_SPY_M)+'.',me);return '';}
function grWk(a,b){return a<b?a+'|'+b:b+'|'+a;}
function grAtWar(a,b){return a!==b&&!!GC.war[grWk(a,b)];}
function grDist(a,b){const A=GCM.P[a],B=GCM.P[b];if(!A||!B)return 0;   /* a lost capital (-1) must not crash a retreat */
  return Math.hypot(A.x-B.x,A.y-B.y);}
function grLog(t,nat){GC.log.push([GC.turn,t,nat||'']);if(GC.log.length>240)GC.log.shift();}
function grAddArmy(o,at,us,name){const N=GC.nat[o];N.an++;const a={id:GC.aid++,o,at,u:us,path:[],pg:0,nm:name||(N.an+(N.an===1?'st':N.an===2?'nd':N.an===3?'rd':'th')+' Army'),from:-1,sup:0,arr:0};GC.armies.push(a);return a;}
function grArmyVal(a){return grForce(grNat(a.o).fac,a.u);}
function grProvDef(pi){const p=GC.prov[pi];return grForce(grNat(p.o).fac,p.gar);}

// ---------- movement graph ----------
// edge cost in turns: land 1, +1 across a major river or into mountains; embark/disembark at ports 1; sea zone = its crossing cost
function grEdge(a,b){const A=GCM.P[a],B=GCM.P[b];if(A.land&&B.land)return 1+((grRiver(a,b)||B.t==='m')?1:0);
  if(A.land&&B.sea)return A.port?1:0;if(A.sea&&B.land)return B.port?1:0;return B.cost;}
// shortest path for nation `o` (Dijkstra, ties by index => deterministic). Foreign provinces are open only when at war (or the goal itself,
// which then means declaring war). Returns {path,turns,decl} or null.
function grPath(o,from,to,fl){if(from===to)return {path:[],turns:0,decl:''};const P=GCM.P,dist=new Map([[from,0]]),prev=new Map(),open=[[0,from]],done=new Set();
  const pass=(j,goal)=>{const q=P[j];if(fl&&!q.sea)return false;if(q.sea)return true;if(gdDmz(j))return false;/* RG44 demilitarised zone */const w=GC.prov[j].o;return w===o||grAtWar(o,w)||goal;};
  while(open.length){open.sort((x,y)=>x[0]-y[0]||x[1]-y[1]);const [d,u]=open.shift();if(done.has(u))continue;done.add(u);if(u===to)break;
    for(const j of P[u].adj){if(done.has(j))continue;const c=grEdge(u,j);if(!c)continue;if(!pass(j,j===to))continue;const nd=d+c;if(!dist.has(j)||nd<dist.get(j)){dist.set(j,nd);prev.set(j,u);open.push([nd,j]);}}}
  if(!dist.has(to))return null;const path=[];for(let c=to;c!==from;c=prev.get(c))path.unshift(c);
  const w=GC.prov[to]&&P[to].land?GC.prov[to].o:'';return {path,turns:dist.get(to),decl:(w&&w!==o&&!grAtWar(o,w))?w:''};}
function grSupplied(a){const P=GCM.P,p=P[a.at];if(p.sea)return true;if(GC.prov[a.at].o===a.o||a.bs===GC.prov[a.at].o||(typeof grAllied==='function'&&grAllied(a.o,GC.prov[a.at].o)))return true;return p.adj.some(j=>P[j].land&&GC.prov[j].o===a.o);}

// ---------- auto-resolve (deterministic strength battle from the same unit lists) ----------
const GR_TDEF={m:.30,u:.15,r:.10,f:0,d:0,c:.05,j:.12,s:.10,w:0};
/* A-REAL strategic depth (world sim, orchestrator 2026-11-07 "Ukraine captured Moscow"): a nation's own heartland and above all its capital are
   defended in depth — reserves, air defence, fortified ring roads, and for nuclear powers the last-ditch deterrent. Scales with the defender's
   real military (GR_REAL) against the attacker's. Counter-play: cut the capital off, wear the reserves down first, or win the war elsewhere. */
/* nuclear-armed = has warheads in Lane G's ONE nuclear system (13zz-gnuke GC.nuk / GNK.start) - a new nuclear power gets the deterrent too */
function grNuk(c){const S=GC&&GC.nuk&&GC.nuk.n&&GC.nuk.n[c];return S?S.w>0:!!(typeof GNK==='object'&&GNK.start[c]);}
function grMilOf(c){return typeof grRealMil==='function'?grRealMil(c,.3):.3;}
function grDepth(pi,an,dn){const p=GCM.P[pi],st=GC.prov[pi];if(!p||!p.land||!st||st.o0!==dn||st.o!==dn)return 0;const md=Math.min(2,grMilOf(dn)),ma=Math.max(.2,grMilOf(an));
  let d=0;if(GC.nat[dn]&&GC.nat[dn].cap===pi){d=.25+.35*md;if(grNuk(dn))d+=.4;}else if(md>=1.2)d=.12*md;
  return d*Math.min(1.5,Math.max(.6,md/ma));}
/* the AI won't march on a nuclear power's capital unless it is at least as strong a military (deterrence) */
function grNukStop(c,j,w){return grNuk(w)&&GC.nat[w]&&GC.nat[w].cap===j&&grMilOf(c)<grMilOf(w);}
/* enemy field armies within reach of c's capital vs what holds it (garrison + armies there) */
function grCapThreat(c){const cap=GC.nat[c].cap;let t=0;for(const x of GC.armies)if(x.o!==c&&!x.fl&&GCM.P[x.at].land&&grAtWar(c,x.o)&&grDist(x.at,cap)<260)t+=grArmyVal(x);return t;}
function grCapHeld(c,skip){const cap=GC.nat[c].cap;let v=GC.prov[cap]&&GC.prov[cap].o===c?grProvDef(cap)*(1+grDepth(cap,'',c)):0;for(const x of GC.armies)if(x.o===c&&x.at===cap&&x!==skip)v+=grArmyVal(x);return v;}
function grDefMods(b){const p=GCM.P[b.p];if(p.sea)return gmilSeaDef(b);let m=1.12+(GR_TDEF[p.t]||0);m+=grDepth(b.p,b.an,b.dn);if(b.river)m+=.2;if(b.mtn)m+=.1;if(GC.prov[b.p].o0===b.dn)m+=.1;if(p.cap)m+=.08;return m;}
function grSideUnits(b,side){const out=[];const ids=side==='att'?b.att:b.def;for(const id of ids){const a=GC.armies.find(x=>x.id===id);if(a)out.push({fac:grNat(a.o).fac,u:a.u,arr:a});}
  if(side==='def'&&b.garr){const p=GC.prov[b.p];out.push({fac:grNat(p.o).fac,u:p.gar,arr:null});}return out;}
function grSideVal(us,def){let v=0;for(const s of us)v+=grForce(s.fac,s.u)*(def!==undefined&&s.arr?gmilMul(s.arr,def):1)*(s.arr&&typeof gmMorMul==='function'?gmMorMul(s.arr):1);return v;}
/* doctrine & fire support (GMOD stats 'attack'/'defense'/'fires', from idea groups) scale a side's auto-resolve strength */
function grIdeaMul(c,st){if(!c||!GC||!GC.nat[c]||typeof gmod!=='function')return 1;return gmod('nation',c,st,1)*gmod('nation',c,'fires',1);}
function grAuto(b,R){const A=grSideUnits(b,'att'),D=grSideUnits(b,'def');const sa=grSideVal(A,0)*(1+R()*.06)*grIdeaMul(b.an,'attack'),sd=grSideVal(D,1)*grDefMods(b)*(1+R()*.06)*grIdeaMul(b.dn,'defense');let pa=sa,pd=sd;
  for(let i=0;i<4;i++){const da=pa*.28,dd=pd*.28;pa=Math.max(0,pa-dd);pd=Math.max(0,pd-da);}
  const attWins=pa>pd,ka=sa?pa/sa:0,kd=sd?pd/sd:0;grApplyLoss(A,attWins?ka:ka*.5,R);grApplyLoss(D,attWins?kd*.5:kd,R);
  return {win:attWins?'att':'def',ka,kd,sa:Math.round(sa),sd:Math.round(sd)};}
// remove (1-k) of each side's units (weakest first, deterministic), wound the rest, and give the survivors some experience
function grApplyLoss(sides,k,R){for(const s of sides){if(s.arr)s.arr.fo=GC.turn;   /* fought this month: burns extra fuel and ammunition (13zl-gsupply.js) */const n=s.u.length,lose=Math.min(n,Math.round(n*(1-Math.min(1,k))));
    const order=s.u.map((r,i)=>[r[1]+R()*30,i]).sort((x,y)=>x[0]-y[0]||x[1]-y[1]);const dead=new Set(order.slice(0,lose).map(o=>o[1]));
    const keep=s.u.filter((r,i)=>!dead.has(i));for(const r of keep){r[1]=Math.max(8,Math.round(r[1]*(.7+.3*Math.min(1,k))));r[2]+=Math.round(60*(1-Math.min(1,k)));r[3]=Math.max(25,r[3]-Math.round(18*(1-Math.min(1,k))));}
    s.u.length=0;for(const r of keep)s.u.push(r);}}

// ---------- the turn ----------
// Order: AI plans (while the player already has theirs) -> movement -> contested provinces (battles) -> capture -> economy -> next turn.
function grEndTurn(auto){if(!GC||GC.over||GC.ph!=='plan')return;try{if(typeof gmMacros==='function')gmMacros();}catch(e){}GC.ph='resolve';try{glgTurn();}catch(e){console.error('glgTurn',e);}grAIPlan();gmilPlan();gmilStrikes();grMovePhase();GC.qi=0;grQueue(auto);}
function grQueue(auto){for(;;){if(GC.qi>=GC.q.length)return grFinishTurn();const b=GC.q[GC.qi];
    if(!auto&&GC.me&&!b.done&&typeof grBattlePrompt==='function'&&(b.an===GC.me||b.dn===GC.me||grSideUnits(b,'att').concat(grSideUnits(b,'def')).some(s=>s.arr&&s.arr.o===GC.me))){grSnap();return grBattlePrompt(b);}   // UI continues via grBattleDone
    if(!auto&&!b.done&&typeof gnBattleFor==='function'){const f=gnBattleFor(b);if(f)return gnBattleAsk(b,f);}   // A2b: a friend's battle waits for that friend (13zn-gnet)
    grBattleAuto(b);GC.qi++;}}
function grBattleAuto(b){if(!b.att.some(id=>GC.armies.some(a=>a.id===id))){b.done=1;return null;}const R=grRng(GC.seed*7+GC.turn*131+b.p);const r=grAuto(b,R);grSettle(b,r.win,'auto');return r;}
function grBattleDone(b,win,how){grSettle(b,win,how||'live');GC.qi++;grSave();return grQueue(false);}
// who stays, who falls back, who dies. `win` is 'att' or 'def'; losers with a province to fall back to keep their survivors, the rest are lost
function grZealArmy(a){try{return msOf(grNat(a.o).fac).rout===0;}catch(e){return false;}}
function grSettle(b,win,how){if(GC.prov[b.p])GC.prov[b.p].hot=GC.turn;try{grLastB(b,win);}catch(e){}try{glBattle(b,win);}catch(e){console.error('glBattle',e);}try{gfBattle(b,win);}catch(e){console.error('gfBattle',e);}try{GC.mil.foe=win==='att'?b.an:b.dn;gmilBattle(b,win);}catch(e){console.error('gmilBattle',e);}   /* the 3D grand map shows battle smoke over contested provinces for a turn or two */const P=GCM.P,att=GC.armies.filter(a=>b.att.includes(a.id)),def=GC.armies.filter(a=>b.def.includes(a.id));
  b.done=1;const pn=P[b.p].n;
  const losers=win==='att'?def:att,winners=win==='att'?att:def;
  for(const a of losers){a.path=[];if(!a.u.length){grDrop(a);continue;}
    if(!a.fl&&grZealArmy(a)){grLog(a.nm+' ('+GCM.nats.get(a.o).name+') fought to the last at '+pn+'.',a.o);grDrop(a);continue;}   /* Zealous never rout or fall back (Abdullah 2026-11-07 22:5x): a beaten army fights to the end - the cost is the whole army */
    let to=a.fl?gmilFleetRetreat(a,b.p):(win==='def'&&a.from>=0&&a.from!==b.p)?a.from:grRetreatTo(a,b.p);
    if(to<0){grLog(a.nm+' ('+GCM.nats.get(a.o).name+') was destroyed at '+pn+'.',a.o);grDrop(a);}else{a.at=to;a.sup=0;grLog(a.nm+' ('+GCM.nats.get(a.o).name+') fell back from '+pn+'.',a.o);}}
  try{gmMorBattle(losers,winners);}catch(e){}
  for(const a of winners){a.path=[];a.from=-1;for(const r of a.u)r[2]+=40;}
  for(const a of GC.armies.slice())if(!a.u.length)grDrop(a);
  if(win==='att'&&GC.prov[b.p]){GC.prov[b.p].gar=[];}
  const an=GCM.nats.get(b.an).name,dn=GCM.nats.get(b.dn).name;
  grLog(pn+': '+(win==='att'?an+' beat '+dn:dn+' held against '+an)+(how==='live'?' (fought live)':how==='retreat'?' (withdrawal)':'')+'.',b.an===GC.me||b.dn===GC.me?GC.me:b.an);try{geSalvage(b,win);}catch(e){}try{wsBattle(b,win);}catch(e){}try{GC.mil.foe='';}catch(e){}}
function grDrop(a){const i=GC.armies.indexOf(a);if(i>=0){GC.armies.splice(i,1);try{gmilLost(a);}catch(e){console.error('gmilLost',e);}}}
function grRetreatTo(a,from){const P=GCM.P;let best=-1,bs=-1e9;for(const j of P[from].adj){if(!P[j].land)continue;const w=GC.prov[j].o;if(w!==a.o)continue;const s=-grDist(j,GC.nat[a.o].cap)*.01+(j===a.from?5:0);if(s>bs){bs=s;best=j;}}return best;}

function grMovePhase(){GC.q=[];const P=GCM.P;
  for(const a of GC.armies.slice().sort((x,y)=>x.id-y.id)){a.arr=0;gdrMove(a);if(!a.path.length)continue;const nx=a.path[0],c=grEdge(a.at,nx);
    if(!c||(P[nx].land&&GC.prov[nx].o!==a.o&&!grAtWar(a.o,GC.prov[nx].o))||gdDmz(nx)){a.path=[];a.pg=0;continue;}   // order no longer legal (peace, border closed, demilitarised zone)
    if(gmilSeaDenied(a,nx))continue;   /* no escort and the sea is held by an enemy fleet: the column waits in port */
    if(geDry(a.o)&&(GC.turn&1))continue;   /* out of fuel: columns crawl, a step every other turn */
    a.pg++;if(a.pg>=c){a.from=a.at;a.at=nx;a.path.shift();a.pg=0;a.arr=GC.turn;}}
  // RV signature "Call to the Shrines" (Abdullah 2026-11-06 21:24): an enemy marching into an RV province with a holy city raises a free volunteer levy there (once per 6 turns)
  for(const p of P){if(!p.land||!GR_HOLY.has(p.n))continue;const st=GC.prov[p.i];if(st.o!=='RV'||(st.lv&&GC.turn-st.lv<6))continue;
    if(GC.armies.some(a=>a.at===p.i&&a.arr===GC.turn&&a.o!=='RV'&&grAtWar(a.o,'RV'))){st.lv=GC.turn;st.gar.push(...grGenUnits('RV',3000,false));grLog('Call to the Shrines: volunteers rise at '+p.n+'!','RV');}}
  // contested provinces: for each province (index order) and each nation that ARRIVED (code order) with someone hostile there
  for(const p of P){const here=GC.armies.filter(a=>a.at===p.i);if(!p.land&&!here.some(a=>a.fl))continue;const arrN=[...new Set(here.filter(a=>a.arr===GC.turn).map(a=>a.o))].sort();
    for(const A of arrN){const att=here.filter(a=>a.o===A&&a.arr===GC.turn),owner=p.land?GC.prov[p.i].o:'';
      const defArm=here.filter(a=>a.o!==A&&grAtWar(A,a.o)&&!(GC.q.some(b=>b.p===p.i&&b.att.includes(a.id))));
      const garr=p.land&&owner!==A&&grAtWar(A,owner)&&GC.prov[p.i].gar.length>0;
      if(!defArm.length&&!garr)continue;if(!p.land&&!(att.some(a=>a.fl)||defArm.some(a=>a.fl)))continue;   // at sea only a fleet starts a fight
      const dn=garr?owner:defArm[0].o,from=att[0].from;
      GC.q.push({p:p.i,an:A,dn,att:att.map(a=>a.id),def:defArm.map(a=>a.id),garr,river:from>=0&&grRiver(from,p.i),mtn:p.t==='m',sea:!p.land,done:0});}}
  GC.q.sort((x,y)=>x.p-y.p||(x.an<y.an?-1:1));for(const b of GC.q)b.v0=geBV(b);}

function grFinishTurn(){const P=GCM.P;try{gmMorTurn();}catch(e){}try{gmRepair();}catch(e){}try{gmilBlockRefresh();}catch(e){}
  // capture: a province whose garrison is gone and which holds only enemy armies changes hands (the strongest occupier takes it)
  for(const p of P){if(!p.land)continue;const st=GC.prov[p.i];const occ=GC.armies.filter(a=>a.at===p.i&&a.o!==st.o&&grAtWar(a.o,st.o)&&a.u.length);
    if(!occ.length||st.gar.length)continue;if(GC.armies.some(a=>a.at===p.i&&a.o===st.o&&a.u.length))continue;
    const by={};for(const a of occ)by[a.o]=(by[a.o]||0)+grArmyVal(a);const taker=Object.keys(by).sort((x,y)=>by[y]-by[x]||(x<y?-1:1))[0],prevO=st.o;
    st.o=taker;st.un=Math.min(100,st.un+35);st.cv=3;st.rq=[];try{gmCaptured(p.i,taker);}catch(e){}try{hsCaptured(p.i,taker,prevO);}catch(e){}try{wsCaptured(prevO,taker);}catch(e){}try{geCaptured(p.i,taker);}catch(e){}grLog(GCM.nats.get(taker).name+' captured '+p.n+' from '+GCM.nats.get(prevO).name+'.',taker===GC.me||prevO===GC.me?GC.me:taker);
    const pn=GC.nat[prevO];if(pn&&pn.cap===p.i){grLog(GCM.nats.get(prevO).name+' lost its capital! (peace talks come in stage 4)',prevO);try{geCapitalFell(prevO,taker);}catch(e){}const rest=P.filter(q=>q.land&&GC.prov[q.i].o===prevO).sort((x,y)=>y.dev-x.dev||x.i-y.i)[0];pn.cap=rest?rest.i:-1;}}
  // economy
  const R=grRng(GC.seed*13+GC.turn);const inc={};geTurnStart();
  for(const p of P){if(!p.land)continue;const st=GC.prov[p.i],c=st.o,N=grNat(c);
    const base=geProvInc(p,st,c);   /* resources + buildings + city tier x autonomy x crises (13g-grandeco.js) */
    const core=gsIsCore(st);const inc1=Math.round(base*GR_TAXK[st.tax]*(1-Math.min(.8,st.un/160))*(core?1:.7));inc[c]=(inc[c]||0)+inc1;
    // unrest drifts toward a target set by the tax rate, recent conquest and being a foreign province
    const tgt=18+GR_TAXU[st.tax]+GE_AUU[st.au|0]-(geFx(c,'calm')?3:0)-6*(st.tr|0)*(st.cf===3?1.5:.3)+(core?0:15)+gmod('nation',c,'unrest',0)+(st.cv>0?25:0)-(GC.nat[c]&&GC.nat[c].cap===p.i?10:0);
    if(st.aut!==undefined&&st.aut!==st.au){if(st.auC>0)st.auC--;else{if(st.aut<st.au){st.au=Math.max(st.aut,st.au-1);st.un=Math.min(100,st.un+10);st.auC=3;}else st.au=Math.min(st.aut,st.au+1);}}st.un+= (tgt-st.un)*.18;st.un=Math.max(0,Math.min(100,st.un));if(st.cv>0)st.cv--;
    if(st.un>72&&R()<.3){const n=Math.floor(st.gar.length/2);st.gar.length=st.gar.length-n;st.un=45;grLog('Revolt in '+p.n+'! The garrison lost '+n+' units.',c===GC.me?c:'');}
    // garrison regrows one unit a turn up to its share, recruits arrive
    const cap=Math.max(2,Math.round(p.dev*1.1))+2*geCount(p.i,'base')+(st.cf===1?(st.tr|0):0)+(GC.nat[c]&&GC.nat[c].cap===p.i&&st.o0===c?Math.round(3*Math.min(2,grMilOf(c)))+(grNuk(c)?2:0):0);   /* A-REAL: capitals keep a reserve garrison sized by the real military */if(st.gar.length<cap&&st.cv===0&&R()<.7){const fac=N.fac;st.gar.push([(st.gar.length%3===2&&grHasKind(fac,'at'))?'at':'inf',100,0,100]);}
    const keep=[];for(const q of st.rq){if(q[0]<=GC.turn){grArrive(c,p.i,q[1],q[2]);}else keep.push(q);}st.rq=keep;}
  geAfterProvinces(inc,R);try{gmilTurnEnd();}catch(e){console.error('gmilTurnEnd',e);}   /* empire economy: trade, oil, fuel, food, manpower, upkeep, bonds, bank, actions, supply (13g-grandeco.js) */
  // supply: an army outside friendly reach loses men every month; on a boat a little
  for(const a of GC.armies){const p=P[a.at];if(grSupplied(a)){a.sup=0;continue;}a.sup++;const rate=p.sea?.03:(p.t==='d'||p.t==='m'||p.t==='s'?.11:.07);const lose=Math.floor(a.u.length*rate+R());
    for(let i=0;i<lose;i++){let w=0;for(let j=1;j<a.u.length;j++)if(a.u[j][1]<a.u[w][1])w=j;a.u.splice(w,1);}for(const r of a.u)r[1]=Math.max(10,r[1]-4);if(lose)grLog(a.nm+' ('+GCM.nats.get(a.o).name+') lost '+lose+' to hunger and exposure at '+p.n+'.',a.o===GC.me?a.o:'');}
  for(const a of GC.armies.slice())if(!a.u.length)grDrop(a);
  // elimination, victory, next turn
  for(const c of Object.keys(GC.nat)){const N=GC.nat[c];if(N.dead)continue;const has=P.some(p=>p.land&&GC.prov[p.i].o===c);const arm=GC.armies.some(a=>a.o===c);if(!has||(N.cap<0&&!arm)){N.dead=1;grLog(GCM.nats.get(c).name+' has been eliminated.',c);for(const a of GC.armies.slice())if(a.o===c)grDrop(a);for(const k of Object.keys(GC.war))if(k.split('|').includes(c))delete GC.war[k];}}
  GC.turn++;GC.ph='plan';GC.q=[];GC.qi=0;try{gmodMonth(GC.turn);}catch(e){}grJudge();grSave();}
function grArrive(c,pi,k,n){const a=GC.armies.find(x=>x.o===c&&x.at===pi&&!x.path.length&&x.nm==='Reserve');const us=[];for(let i=0;i<n;i++)us.push([k,100,0,100]);if(a)a.u.push(...us);else{const b=grAddArmy(c,pi,us,'Reserve');}}

// ---------- victory ----------
function grScore(c){let s=0;const N=GC.nat[c];for(const p of GCM.P){if(!p.land||GC.prov[p.i].o!==c)continue;s+=10;}for(const w of N.wg)if(GC.prov[w].o===c)s+=25;let v=0;for(const a of GC.armies)if(a.o===c)v+=grArmyVal(a);return Math.round(s+v/2000);}
function grWins(c){const N=GC.nat[c],reg=grNat(c).reg;let cnt=0,tot=0;for(const p of GCM.P)if(p.land){tot++;if(GC.prov[p.i].o===c)cnt++;}
  if(cnt/tot>=.35)return 'holds '+Math.round(cnt/tot*100)+'% of the world';
  // all war-goal provinces of every other nation in your own region (those that are still alive)
  const foes=Object.keys(GC.nat).filter(k=>k!==c&&grNat(k).reg===reg&&grNat(k).major);if(foes.length&&foes.every(k=>GC.nat[k].dead||GC.nat[k].wg.every(w=>GC.prov[w].o===c)))return 'took every war goal in its region';
  return '';}
function grJudge(){if(!GC.me||GC.over)return;const me=GC.me;if(GC.nat[me].dead){GC.over='lose';GC.res='Your nation has fallen.';return;}
  const w=grWins(me);if(w){GC.over='win';GC.res=GCM.nats.get(me).name+' '+w+'.';return;}
  if(GC.turn>GC.maxTurn){const sc=Object.keys(GC.nat).filter(c=>!GC.nat[c].dead).map(c=>[c,grScore(c)]).sort((a,b)=>b[1]-a[1]||(a[0]<b[0]?-1:1));GC.over=sc[0][0]===me?'win':'lose';GC.res='The campaign ends. '+GCM.nats.get(sc[0][0]).name+' leads with '+sc[0][1]+' points'+(sc[0][0]===me?'.':' (you: '+grScore(me)+').');}}

// ---------- player orders ----------
function grOrderMove(aid,to){const a=GC.armies.find(x=>x.id===aid);if(!a||a.o!==GC.me||GC.ph!=='plan')return {err:'no army'};const r=grPath(a.o,a.at,to,a.fl);if(!r)return {err:a.fl?'Fleets sail between sea zones only.':'No route (check ports, seas and borders).'};
  if(r.decl)return {decl:r.decl,r};a.path=r.path;a.pg=0;a.dg=0;return {ok:1,r};}
function grDeclare(a,b){if(typeof gdTruce==='function'&&gdTruce(a,b))return;if(typeof grOverlord==='function'&&grOverlord(a))return;GC.war[grWk(a,b)]=1;grLog(GCM.nats.get(a).name+' declared war on '+GCM.nats.get(b).name+'.',a);try{if(typeof gescDeclared==='function')gescDeclared(a,b);}catch(e){console.error('gescDeclared',e);}try{glgDeclare(a,b);}catch(e){console.error('glgDeclare',e);}}   // laneG: allies/guarantors join
function grRecruit(c,pi,k){const st=GC.prov[pi];if(st.o!==c)return 'Not your province.';const fac=grNat(c).fac,rc=GR_RECRUIT.find(r=>r[0]===k);if(!rc||!grHasKind(fac,k))return 'Not available.';const T=geRecruitTerms(c,pi,k,rc[1]),cost=T.cost;
  if(GC.nat[c].cash<cost)return 'Not enough money.';if(GC.nat[c].e.man<T.man)return 'Not enough manpower ('+Math.round(GC.nat[c].e.man)+' of '+T.man+').';GC.nat[c].cash-=cost;GC.nat[c].e.man-=T.man;st.rq.push([GC.turn+T.turns,k,rc[1]]);return '';}
function grSetTax(c,pi,i){const st=GC.prov[pi];if(!st||st.o!==c)return 'Not your province.';st.tax=Math.max(0,Math.min(2,i|0));return '';}   /* A2b: one function so online friends' tax orders reach the host */
function grSplit(aid){const a=GC.armies.find(x=>x.id===aid);if(!a||a.u.length<2)return null;const h=Math.floor(a.u.length/2);const mv=a.u.splice(a.u.length-h,h);const b=grAddArmy(a.o,a.at,mv);if(a.fl)b.fl=1;return b;}
function grMerge(aid){const a=GC.armies.find(x=>x.id===aid);if(!a)return 0;let n=0;for(const b of GC.armies.slice())if(b!==a&&b.o===a.o&&b.at===a.at&&!b.path.length&&!b.fl===!a.fl){a.u.push(...b.u);try{gmilMerge(a,b);}catch(e){}grDrop(b);n++;}return n;}

// ---------- AI empires ----------
/* AI army orders (merge idle columns, march on the weakest reachable enemy province, keep the capital held); run at month end and, in real time, on days 10 and 20 (grAIMid) */
function grAIArmies(c,R,wars){const P=GCM.P;
    const mineA=GC.armies.filter(a=>a.o===c&&!a.fl).sort((a,b)=>a.id-b.id);for(const a of mineA)if(!a.path.length)grMerge(a.id);
    {const cap=GC.nat[c].cap;for(const a of mineA)if(a.at===cap&&a.path.length&&GC.prov[cap].o===c&&grCapHeld(c,a)<grCapThreat(c)*1.2){a.path=[];a.pg=0;}}   /* A-REAL: a column about to leave a threatened capital stays */
    for(const a of GC.armies.filter(x=>x.o===c&&!x.path.length&&!x.fl&&!x.fr).sort((x,y)=>x.id-y.id)){const val=grArmyVal(a);if(val<2500)continue;if(typeof gsupHold==='function'&&gsupHold(a)){gsupFallBack(a);continue;}   /* real supply: short of fuel or ammunition - halt and refill before a new attack (fall back if the line is cut) */
      const home=GCM.P[a.at].land&&GC.prov[a.at].o===c;let tgt=-1,ts=-1e9;
      {const cap=GC.nat[c].cap;if(home&&cap>=0&&a.at!==cap&&GC.prov[cap].o===c&&grDist(a.at,cap)<420&&grCapHeld(c,null)+GC.armies.filter(x=>x.o===c&&x.path.length&&x.path[x.path.length-1]===cap).reduce((s,x)=>s+grArmyVal(x),0)<grCapThreat(c)*1.2){const r=grPath(c,a.at,cap);if(r&&!r.decl){a.path=r.path;continue;}}}   /* A-REAL: the capital is threatened and thin - fall back to defend it */
      const seen=new Set([a.at]),seaN=new Set(),blue=grMilOf(c)>=1;let fr=[a.at];for(let d=0;d<5&&fr.length;d++){const nx=[];for(const u of fr)for(const j of P[u].adj){if(seen.has(j))continue;seen.add(j);if(!P[j].sea)nx.push(j);else if(P[u].port||P[u].sea){nx.push(j);}if(P[j].sea||seaN.has(u))seaN.add(j);
        if(P[j].land){const w=GC.prov[j].o;if(w!==c&&wars.includes(w)&&!grNukStop(c,j,w)&&(blue||!seaN.has(j))){   /* A-REAL: only real militaries (GR_REAL mil >= 1) mount invasions across the sea */const def=(grProvDef(j)*1.25+GC.armies.filter(x=>x.at===j&&x.o===w).reduce((s,x)=>s+grArmyVal(x),0))*(1+grDepth(j,c,w));const sc=(P[j].wg?40:0)+P[j].dev*4+(val/Math.max(300,def)-1)*30-d*8;if(def<val*1.1&&sc>ts){ts=sc;tgt=j;}}}}fr=nx;}
      if(tgt<0&&home){const cap=GC.nat[c].cap;if(a.at!==cap&&R()<.15&&val>6000){const r=grPath(c,a.at,cap);if(r&&!r.decl){a.path=r.path;}}continue;}
      if(tgt>=0){const keepHome=GC.nat[c].cap===a.at&&((mineA.filter(x=>x.at===a.at).length===1&&wars.some(w=>GC.nat[w]&&GCM.P[GC.nat[w].cap]&&grDist(a.at,GC.nat[w].cap)<260))||grCapHeld(c,a)<grCapThreat(c)*1.2);if(keepHome)continue;const r=grPath(c,a.at,tgt);if(r&&!r.decl)a.path=r.path;}}
}
/* A2 real time: AI generals think on day ticks too — on days 10 and 20 every AI nation at war sends its idle columns off (army orders only: no recruiting, taxes or declarations, those stay monthly). Deterministic from seed + month + day; marks the departure day so the column slides from where it stands */
function grAIMid(day){if(!GC||GC.ph!=='plan'||GC.over)return 0;const R=grRng(GC.seed*17+GC.turn*3+day*977);let n=0;
  for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead||!N.ai)continue;const wars=Object.keys(GC.war).filter(k=>k.split('|').includes(c)).map(k=>k.split('|').find(x=>x!==c));if(!wars.length)continue;
    const idle=new Set(GC.armies.filter(a=>a.o===c&&!a.path.length).map(a=>a.id));grAIArmies(c,R,wars);
    for(const a of GC.armies)if(idle.has(a.id)&&a.path.length){a.sd=day;a.sm=GC.turn;a.pg=0;n++;}}
  return n;}
function grAIPlan(){const R=grRng(GC.seed*17+GC.turn*3),P=GCM.P;
  for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead||!N.ai)continue;const fac=grNat(c).fac,mine=P.filter(p=>p.land&&GC.prov[p.i].o===c);if(!mine.length)continue;
    const wars=Object.keys(GC.war).filter(k=>k.split('|').includes(c)).map(k=>k.split('|').find(x=>x!==c));
    // a nation at peace with everyone picks a fight with its weakest neighbour now and then (minor nations only defend)
    if(!wars.length&&grNat(c).major&&GC.turn>=3&&R()<.15){let best=null,bv=1e18;for(const p of mine)for(const j of p.adj){const q=P[j];if(!q.land)continue;const w=GC.prov[j].o;if(w===c||GC.nat[w].dead||grAllied(c,w)||grOpinion(c,w)>=40)continue;const v=grProvDef(j)+GC.armies.filter(a=>a.at===j).reduce((s,a)=>s+grArmyVal(a),0);if(v<bv||(v===bv&&w<best)){bv=v;best=w;}}if(best&&(typeof gescGate!=='function'||gescGate(c,best,R))){grDeclare(c,best);wars.push(best);}}
    // recruit: keep a reserve, spend the rest at the frontier province (or the capital)
    if((grNat(c).major||wars.length)&&!((typeof gfOver==='function'&&gfOver(c))||(N.e&&N.e.br&&(N.inc|0)<0))||(wars.length&&grCapHeld(c,null)<grCapThreat(c))){const front=mine.map(p=>[p,p.adj.filter(j=>P[j].land&&GC.prov[j].o!==c&&(wars.includes(GC.prov[j].o))).length*3+(p.i===N.cap?1:0)]).sort((a,b)=>b[1]-a[1]||a[0].i-b[0].i)[0][0];
      let guard=0;while(N.cash>1500&&guard++<6){let k=GR_RECRUIT.filter(r=>grHasKind(fac,r[0]))[Math.floor(R()*3.4)%4]||GR_RECRUIT[0];if(GC.turn%5===2&&grHasKind(fac,'drone')){const dk=GR_RECRUIT.find(r=>r[0]==='drone');if(dk)k=dk;}   /* gair: AI buys drones by the same rules */if(grRecruit(c,front.i,k[0]))break;}}
    // armies: merge idle ones at the same place, then march on the weakest reachable enemy province; keep the capital defended
    grAIArmies(c,R,wars);
    // tax: AI keeps rear provinces on High, the front on Normal
    for(const p of mine){const st=GC.prov[p.i],fr=p.adj.some(j=>P[j].land&&grAtWar(c,GC.prov[j].o));st.tax=st.un>55?0:fr?1:(st.un<35?2:1);}}
  geAIAll();}   /* empire economy for AI nations: bonds, bank, buildings, total war, embargoes, merchants... (13g-grandeco.js) */

// ---------- save ----------
/* calendar: month 1 = the start month GC.m0 (0-based from Jan 2026; new campaigns = GR_REAL.asof = Nov 2026, A-DATE; saves without m0 = Jan 2026); GC.day = days into the current month (0..29), ticked by the real-time clock in 13c */
const GR_MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
/* real time: how far (0..0.92) a marching army has got along its current road, from progress months + days into this month (display only, sim unchanged) */
function grSlide(a){if(!GC||GC.ph!=='plan'||!a.path||!a.path.length)return 0;const c=grEdge(a.at,a.path[0]);if(!c)return 0;let d=Math.min(29.99,(GC.day|0)+((typeof GV!=='undefined'&&GV.dayF)||0));if(a.sm===GC.turn&&a.sd>0)d=Math.max(0,(d-a.sd)*30/(30-a.sd));return Math.max(0,Math.min(.985,((a.pg|0)+d/30)/c));}   /* Abdullah 20:40 smoother marches: slide nearly all the way, then a short blend on arrival */
function grM0(){return (typeof GC==='object'&&GC&&GC.m0|0)||0;}
function grMonStr(turn){const m=Math.max(0,(turn|0)-1)+grM0();return GR_MON[m%12]+' '+(2026+Math.floor(m/12));}   /* A2c: month label for former 'turn N' wording */
function grDateStr(turn,day){const m=Math.max(0,(turn|0)-1)+grM0();return ((day|0)+1)+' '+GR_MON[m%12]+' '+(2026+Math.floor(m/12));}
/* grInfo: a tiny note next to the save (when, who, which month) so the main menu can offer "Continue" without loading the campaign code */
/* grWarTable (living main menu): a small sketch of the map around the player's nation - who owns each cell of a 480x270 window, run-length packed - plus the place of the last battle.
   It rides in the save's note so the main menu can draw the war table without loading the campaign code. Display only. */
function grWarTable(lb){try{if(!GC||!GC.me||typeof guCols!=='function'||typeof document==='undefined')return null;const idx=guCols(),P=GCM.P,me=GC.me,W=480,H=270;
  const xs=[],ys=[];for(const p of P)if(p.land&&GC.prov[p.i]&&GC.prov[p.i].o===me){xs.push(p.x);ys.push(p.y);}const n=xs.length;if(!n)return null;xs.sort((a,b)=>a-b);ys.sort((a,b)=>a-b);
  const lo=Math.floor(n*.1),hi=Math.ceil(n*.9)-1,x0=xs[lo],x1=xs[Math.max(lo,hi)],y0=ys[lo],y1=ys[Math.max(lo,hi)];   /* the middle 80% of your provinces: far-off islands and exclaves do not drag the view away from the homeland */
  const cx=(x0+x1)/2,cy=(y0+y1)/2,vw=Math.min(GM_W,Math.max(340,(x1-x0+110)/.4,(y1-y0+110)/.55*16/9)),vh=vw*9/16;
  const vx=Math.max(0,Math.min(GM_W-vw,cx-vw*.66)),vy=vh>=GM_H?(GM_H-vh)/2:Math.max(0,Math.min(GM_H-vh,cy-vh*.5));
  const pal=new Map(),out=[];let pv=-1,run=0;const put=()=>{if(run<1)return;out.push(pv);let r=run;while(r>127){out.push((r&127)|128);r>>=7;}out.push(r);};
  for(let j=0;j<H;j++){const y=Math.floor((vy+(j+.5)*vh/H)/GU_K);for(let i=0;i<W;i++){const x=Math.floor((vx+(i+.5)*vw/W)/GU_K);let v=0;
    if(y>=0&&y<GU_RH&&x>=0&&x<GU_RW){const p=P[idx[y*GU_RW+x]];if(p&&!p.sea){const o=GC.prov[p.i]?GC.prov[p.i].o:'';if(o===me)v=1;else{v=pal.get(o);if(!v){v=2+pal.size%250;pal.set(o,v);}}}}
    if(v===pv)run++;else{put();pv=v;run=1;}}}put();
  let d='';for(let i=0;i<out.length;i+=8192)d+=String.fromCharCode.apply(null,out.slice(i,i+8192));
  const sc=lb&&P[lb.p]?lb:null;
  const fx=p=>+((p.x-vx)/vw).toFixed(4),fy=p=>+((p.y-vy)/vh).toFixed(4);let b=null;if(sc&&P[sc.p]){const q=P[sc.p],X=fx(q),Y=fy(q);if(X>.03&&X<.97&&Y>.05&&Y<.95)b=[X,Y,q.n,grMonStr(sc.t),sc.w?1:0];}
  return {w:W,h:H,d:btoa(d),c:(typeof grNatRgb==='function'?grNatRgb(me):[200,170,80]).map(v=>Math.round(v)),b};}catch(e){return null;}}
/* grLastB: where and when YOUR nation last fought, and whether it won. Display only: it lives in a module variable and in the save's small note (GR_KEY+'.i'),
   never in GC, so it is not part of the campaign state, the saves' simulation data or the multiplayer checkpoint. */
let GR_LASTB=null;
function grLastB(b,win){if(!GC||!GC.me||!b||(b.an!==GC.me&&b.dn!==GC.me))return;GR_LASTB={p:b.p,t:GC.turn,w:((win==='att')===(b.an===GC.me))?1:0,me:GC.me,s:GC.seed|0};}
function grLastBGet(){let lb=GR_LASTB;const ok=o=>o&&o.me===GC.me&&(o.s|0)===(GC.seed|0)&&o.t<=GC.turn;if(!ok(lb)){lb=null;try{const o=JSON.parse(localStorage.getItem(GR_KEY+'.i'));if(o&&ok(o.lb))lb=o.lb;}catch(e){}}return lb;}
function grInfo(){try{if(!GC)return;const lb=grLastBGet(),wt=grWarTable(lb),o={ts:Date.now(),me:GC.me||'',n:GC.me?((GCM&&GCM.nats&&GCM.nats.get(GC.me)||{}).name||GC.me):'Observer',d:grMonStr(GC.turn),over:GC.over?1:0};if(lb){o.lb=lb;o.lbn=(GCM.P[lb.p]||{}).n||'';o.lbd=grMonStr(lb.t);}if(wt)o.wt=wt;localStorage.setItem(GR_KEY+'.i',JSON.stringify(o));}catch(e){}}   // lint-ok (save timestamp, not simulation)
function grSave(){try{localStorage.setItem(GR_KEY,JSON.stringify(GC));GR_AUTO.t=Date.now();grInfo();}catch(e){}}   // lint-ok (save timestamp, not simulation)
/* rolling safety copies before every Fight-it battle (queue "Never lose progress"): newest = GR_KEY+'.b1', then .b2, .b3; grLoad falls back to them if the main save is damaged */
function grSnap(){try{if(!GC||(typeof GNT!=='undefined'&&GNT.on&&!GNT.host))return;const js=JSON.stringify(GC),K=GR_KEY+'.b';
  try{localStorage.setItem(GR_KEY,js);}catch(e){try{for(let i=3;i>=1;i--)localStorage.removeItem(K+i);localStorage.setItem(GR_KEY,js);}catch(_){}}   // the main save always comes first; a full storage costs the copies, never the save
  GR_AUTO.t=Date.now();grInfo();   // lint-ok (save timestamp, not simulation)
  try{for(let i=3;i>1;i--){const v=localStorage.getItem(K+(i-1));if(v)localStorage.setItem(K+i,v);}localStorage.setItem(K+'1',js);}catch(e){try{localStorage.removeItem(K+'3');localStorage.removeItem(K+'2');localStorage.setItem(K+'1',js);}catch(_){}}}catch(e){}}
/* autosave on a timer (queue "Never lose progress"): every 3 minutes with the world map open (not during a battle, not as a guest in a friend's campaign) the campaign
   is saved and a rolling copy kept; leaving or hiding the page saves too. Same save + same 3 copies as the Fight-it safety copy - one system. */
const GR_AUTO={t:Date.now(),ms:180000};   // lint-ok (save timestamp, not simulation)
function grAutoOk(){return !!(GC&&!GC.over&&document.getElementById('grandScreen')&&!(typeof G!=='undefined'&&G&&!G.over)&&!(typeof GNT!=='undefined'&&GNT.on&&!GNT.host));}
function grAutoTick(force){if(!grAutoOk())return false;if(!force&&Date.now()-GR_AUTO.t<GR_AUTO.ms)return false;grSnap();return true;}   // lint-ok (save timestamp, not simulation)
try{setInterval(()=>{try{grAutoTick();}catch(e){}},15000);addEventListener('pagehide',()=>{try{if(grAutoOk())grSave();}catch(e){}});document.addEventListener('visibilitychange',()=>{try{if(document.hidden&&grAutoOk())grSave();}catch(e){}});}catch(e){}
// a save made on an older world map (the province list changed, e.g. 2026-11-06 real borders 174 -> 236 land provinces) can't
// continue: its province indices point at different places, so the map breaks and a Fight-it battle never loads (Lane A1)
function grMapSig(){grMap();let h=0;for(const p of GCM.P){const s=p.n+'/'+p.adj.length;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))|0;}return GCM.P.length+':'+(h>>>0).toString(36);}
function grSaveOk(o){if(!o||o.v!==1||!Array.isArray(o.prov))return false;grMap();return o.ms?o.ms===grMapSig():o.prov.length===GCM.P.length;}
function grLoad(){try{let s=localStorage.getItem(GR_KEY);if(!s)return null;grMap();let o=null;try{o=JSON.parse(s);}catch(e){}if(!grSaveOk(o)){o=null;for(let i=1;i<=3&&!o;i++){try{const t=JSON.parse(localStorage.getItem(GR_KEY+'.b'+i));if(grSaveOk(t))o=t;}catch(e){}}}if(!o)return null;if(!o.ms)o.ms=grMapSig();GC=o;try{geEnsure();}catch(e){}try{grResBloc();grVasInit();}catch(e){}return GC;}catch(e){return null;}}
