  h+='<div style="border-top:1px solid #2c4358;padding-top:4px">'+geRow('Fuel',Math.round(E.fuel)+' / 400  (burn '+(br.fuelN||0)+'/month)',E.dry?'#ff9d8e':null)+geRow('Food',Math.round(E.food)+'  ('+geSgn(br.food||0)+'/month)',E.starve?'#ff9d8e':null)+geRow('Manpower',Math.round(E.man)+' / '+geManCap(me))+geRow('Power grid',Math.round(E.pw*100)+'%'+(E.pw<1?' (blackouts slow factories and recruiting)':''),E.pw<.8?'#ff9d8e':null)+geRow('Oil stock / world price',Math.round(E.oil)+' / '+GC.eco.oilIdx+'%')+'</div>';
