  let d=sec('War bonds ($'+GE_BOND+' now, repaid with interest in 10 months)');d.appendChild(guEl('div','font-size:13px','Owed $'+k.d+' of $'+k.cap+' limit'+(E.defT>GC.turn?' · <span style="color:#ff9d8e">credit frozen</span>':'')+(E.bonds.length?' · next due '+grMonStr(Math.min(...E.bonds.map(b=>b[0]))):'')));let r=row();r.appendChild(geBtn('Issue bond',()=>geDone(geBorrow(me))));r.appendChild(geBtn('Repay oldest',()=>geDone(geRepay(me)),E.bonds.length>0));d.appendChild(r);
  d=sec('Central bank (safe reserve, pays '+(geFx(me,'bank')?'2':'1')+'% a month, lootable if your capital falls)');d.appendChild(guEl('div','font-size:13px','Reserve $'+Math.round(E.bank).toLocaleString()));r=row();r.appendChild(geBtn('Deposit $1000',()=>geDone(geDeposit(me,1000))));r.appendChild(geBtn('Withdraw all',()=>geDone(geWithdraw(me)),E.bank>0));d.appendChild(r);
  d=sec('Home front');r=row();r.appendChild(geBtn(E.tw?'Total war: ON':'Total war: off',()=>geDone(geTotalWar(me,!E.tw)),true,'Faster recruiting and more manpower, +15% upkeep, rising unrest. Only at war.'));r.appendChild(geBtn(E.ration?'Rationing: ON':'Rationing: off',()=>geDone(geRation(me,!E.ration)),true,'-20% food use, unrest +3 a month. Besieged provinces hold out.'));
