/* ingameui slice 1: the province panel's Build and Govern tabs (13c guSide) — buildings as icon cards with slots, one tab per job */
function geUiBuild(box,pi){const p=GCM.P[pi],st=GC.prov[pi],me=GC.me;if(!p||!p.land||!me||st.o!==me)return;const bl=geBl(pi),used=geUsed(pi),sl=geSlots(pi);
  box.appendChild(UK.sec('Buildings',used+' / '+sl+' slots'));const sw=guEl('div','display:flex;flex-wrap:wrap;gap:4px;margin-bottom:4px');
  for(const r of bl){const B=GE_B[r[0]],d=guEl('span','display:inline-flex;align-items:center;gap:5px;padding:4px 7px;border-radius:4px;font-size:13px;background:'+B[4]+'22;border:1px solid '+B[4]);d.innerHTML='<b style="color:'+B[4]+'">'+B[3]+'</b> '+B[0]+(r[1]>0?' <span style="color:#ff9d8e">−'+r[1]+'%</span>':'');d.dataset.tt=JSON.stringify({t:B[0],d:B[5],r:r[1]>0?[['Damaged',r[1]+'%']]:[]});sw.appendChild(d);}
  for(let i=used;i<sl;i++){const d=guEl('span','display:inline-block;width:30px;height:27px;border-radius:4px;border:1px dashed #3a5168');d.dataset.tt='Empty building slot';sw.appendChild(d);}box.appendChild(sw);
  if(st.bq.length){const q=guEl('div','');q.className='uk-q';q.textContent='Under construction: '+st.bq.map(q=>GE_B[q[1]][0]+' (due '+grMonStr(q[0])+')').join(' · ');box.appendChild(q);}
  box.appendChild(UK.sec('Construct','click to order'));const g=guEl('div','');g.className='uk-grid';
  for(const k of GE_BKEYS){const why=geCanBuild(me,pi,k);if(why&&/foreign|Not your|Unknown|no Mountain|mountain|No farmland|No mining|Not on the coast|Already has|oil province/i.test(why))continue;const B=GE_B[k],c=geCost(me,k);
    g.appendChild(UK.card({icon:B[3],col:B[4],name:B[0],meta:'<b>$'+c+'</b> · '+B[2]+' mo',on:!why,why,desc:B[5],rows:[['Cost','$'+c],['Build time',B[2]+' months'],['Slots',used+' / '+sl]],onclick:()=>geDone(geBuild(me,pi,k)),onDenied:()=>{GV.hint=why;guHint();}}));}
  box.appendChild(g);}
function geUiGovern(box,pi){const p=GCM.P[pi],st=GC.prov[pi],me=GC.me;if(!p||!p.land||!me||st.o!==me)return;const E=GC.nat[me].e,cur=st.aut===undefined?st.au:st.aut;
  box.appendChild(UK.sec('Autonomy',st.au!==st.aut&&st.aut!==undefined?'changing to '+GE_AU[st.aut]+'…':''));
  box.appendChild(UK.seg(GE_AU,cur,i=>geDone(geAutonomy(me,pi,i)),['Direct rule — full tax and manpower; most unrest','Local rule — calmer, less tax and manpower','Autonomous — calmest, least tax and manpower. Lowering autonomy later takes time and stirs unrest']));
  box.appendChild(UK.sec('City',(['Town','City','Metropolis'][st.tr|0])+(st.cf>=0?' · '+GE_CITY[st.cf]:'')+(st.ctp?' · growing, done '+grMonStr(st.ctp):'')));
  if((st.tr|0)<2&&!st.ctp){const g=guEl('div','');g.className='uk-grid';const cc=geCityCost(st);GE_CITY.forEach((n,i)=>{if((st.tr|0)>0&&st.cf!==i)return;const ok=GC.nat[me].cash>=cc&&!(i===2&&!p.coast);
      g.appendChild(UK.card({icon:'▲',col:'#e3b341',name:'Grow: '+n,meta:'<b>$'+cc+'</b>',on:ok,why:i===2&&!p.coast?'Needs a coast':'Not enough money',desc:n==='Industrial'?'+12% income a tier, cheaper recruits':n==='Military'?'+garrison, faster training, a fort in the battle':n==='Port'?'a port in the battle, trade':'much calmer',onclick:()=>geDone(geCity(me,pi,i))}));});box.appendChild(g);}
  box.appendChild(UK.sec('Actions'));const r3=guEl('div','');r3.className='uk-acts';const mi=E.mer.includes(pi);
  r3.appendChild(UK.link(mi?'Recall merchant':'Place merchant',()=>geDone(geMerchant(me,pi,!mi)),'A merchant skims part of this province\'s trade toward you.'));
  if(!p.cap)r3.appendChild(UK.link('Scorched earth $150',()=>guConfirm('Scorched earth?','Destroys the works here and halves income for 5 months, +25 unrest. An enemy taking it gets nothing.',()=>geDone(geAct(me,'scorch',pi))),'Destroys the works and halves income for 5 months, +25 unrest; an enemy taking it gets nothing.',1));box.appendChild(r3);
  if(E.ord.some(o=>o[1]===pi))box.appendChild(guEl('div','font-size:12px;color:#ffd24a;margin-top:4px','Ordered this month: '+E.ord.filter(o=>o[1]===pi).map(o=>o[0]).join(', ')));}
function geUiProv(s,pi){const p=GCM.P[pi],st=GC.prov[pi],me=GC.me;if(!p||!p.land||!me)return;const mine=st.o===me,E=GC.nat[me].e;
  const box=guEl('div','margin:8px 0;border-top:1px solid #2c4358;padding-top:6px');
  if(mine){geUiBuild(box,pi);geUiGovern(box,pi);   /* ingameui: the province panel calls these per tab */
  }else if(grAtWar(me,st.o)){
    box.innerHTML='<div style="opacity:.75;font-size:13px">Economic war</div>';const row=guEl('div','display:flex;flex-wrap:wrap;gap:4px;margin-top:3px');
    row.appendChild(geBtn('Strategic bombing $250',()=>geDone(geAct(me,'bomb',pi)),true,'Needs an airfield within range. Damages a factory, refinery, power plant, mine, port or airfield (AA halves it). 8 fuel.'));
    row.appendChild(geBtn('Loot',()=>geDone(geAct(me,'loot',pi)),true,'Needs your army in the province: cash now, +30 unrest there, income -20% for 5 months. Hurts your world opinion.'));box.appendChild(row);
    if(E.ord.some(o=>o[1]===pi))box.appendChild(guEl('div','font-size:12px;color:#ffd24a;margin-top:2px','Ordered this month: '+E.ord.filter(o=>o[1]===pi).map(o=>o[0]).join(', ')));
    const mi=E.mer.includes(pi);
  }else{const mi=E.mer.includes(pi);box.innerHTML='';box.appendChild(geBtn(mi?'Recall merchant':'Place merchant here',()=>geDone(geMerchant(me,pi,!mi)),true,'A merchant skims part of this province\'s trade toward you ($70/month).'));}
  if(box.innerHTML||box.childNodes.length)s.appendChild(box);}
// ===== 13i-grandmil: grand stage 3 - MILITARY on the grand map (prefix gmil*) =====
// Generals (named, fictional, traits, levels, killed/captured), front lines (hold / push / counter, AI-assist), map strikes
// (missile / air raid / drone against buildings, armies or fleets, air defence intercepts), fleets & sea zones (a fleet is an
// army with a.fl=1 made of ships, so movement, battles, saves and the 3D map reuse the army code), blockades (cut port income
// and sea trade of 13g-grandeco), escorts for crossings, mines and subs. AI empires use all of it. Everything here is
// deterministic: random draws come from grRng seeded with the campaign seed, the turn and a stable index.
// State: GC.mil = {g:{id:general}, gid, fr:[fronts], fid, zm:{zone:{o,n}}, fq:[fleet queue], n:{nation:{ms,so}}, bk:{province:1}, foe}
