/* RANGES (orch/RANGES.md): grand map = Equal Earth 2400x1200 units ~ 14 km/unit. Real reach: missile 2,000 km (Shahab-3/Tomahawk/Jericho class), air raid 1,000 km (strike-jet combat radius), Shahed-type drone 2,000 km. Flight: ballistic ~12 min, cruise ~800 km/h, drone ~185 km/h - all inside the monthly turn. */
const GMIL_KMU=14,GMIL_KM={m:2000,a:1000,d:2000};
const GMIL_ST={m:{n:'Missile',cost:0,fuel:0,rng:Math.round(GMIL_KM.m/GMIL_KMU),km:GMIL_KM.m,dmg:55,ic:1},a:{n:'Air raid',cost:180,fuel:6,rng:Math.round(GMIL_KM.a/GMIL_KMU),km:GMIL_KM.a,dmg:15,ic:.85},d:{n:'Drone strike',cost:0,fuel:0,rng:Math.round(GMIL_KM.d/GMIL_KMU),km:GMIL_KM.d,dmg:6,ic:1}};
// One-way attack drones (Shahed/Geran-type): ground racks and mobile launchers, no runway; cruise ~185 km/h.
const GMIL_DKMH=185,GMIL_DR_MAX=60,GMIL_DR_COST=30,GMIL_LN_COST=120,GMIL_LN_MAX=3,GMIL_SALVO=12;
const GMIL_DRN=['IR','RS','DW','RV','RU','UA','KP','PK','IN','IL','CN','TR','US'];
const GMIL_DR0={IR:24,RS:16,DW:12,RV:8,RU:24,UA:12,KP:10};
const GMIL_MISSILE_COST=450;
/* STOCKPILES THAT RUN OUT (campaign realism 2). One counted stock per nation in GC.mil.n[c]: ms = long-range missile salvos (1 = ~50 missiles),
   ic = air-defence interceptor loads (1 = ~25 Patriot / S-300-class rounds), dr = one-way drones. Real Nov-2026 levels and factory rates:
   orch/REAL-2026.md "Munition stockpiles". Row = [missiles now, depot size, made per year, interceptors now, depot size, made per year].
   Chain: firing spends stock; defending spends interceptors (2 per missile salvo, 1 per air-raid sortie, 1 per 4 drones) and batteries without
   rounds stop nothing; an emptied defence is world news and costs war support at home (the one meter, 13v); AI attackers prefer targets that have run dry;
   factories refill slowly, a paid order takes months (longer for importers, none under UN sanctions); allies can ship theirs - the receiver's
   enemies hold it against the sender. Counter-play: keep a reserve, saturate with cheap drones first, order early, ask friends. */
const GMIL_STK={US:[5,8,3,14,40,14],RU:[6,8,10,24,36,10],CN:[8,8,8,30,36,12],IL:[4,6,3,8,24,7],IR:[2,6,5,3,12,2],UA:[1,3,2,4,16,1],KP:[4,6,3,4,10,1],IN:[4,6,3,12,20,4],
  PK:[3,5,2,6,12,2],SA:[2,4,0,6,20,0],AE:[1,3,0,5,16,0],TR:[2,4,2,5,10,2],EG:[2,4,1,6,12,1],FR:[2,4,2,6,12,3],DE:[1,3,1,6,12,3],PL:[1,3,1,6,12,2],GB:[2,4,2,5,10,2],
  JP:[2,5,2,10,16,3],KR:[4,6,4,10,16,3],RS:[1,3,1,0,2,0],DW:[2,4,1,0,2,0],RV:[1,2,1,0,2,0],OB:[0,2,1,0,1,0],BI:[0,1,0,0,1,0]},GMIL_STK_D=[1,2,1,2,6,1];
/* Shells and precision bombs (stockpiles slice 2) — the same counters, two more kinds. Units: 1 shell load = about 100,000 artillery rounds,
   1 precision bomb load = about 2,500 guided bombs / kits (orch/REAL-2026.md "Shells and guided bombs"). Row = [shells now, depot, made per year, bombs now, depot, made per year].
   Chain: an army that fought this month burns shells from the national stock (25 thousandths of a load per unit); with the stock at zero every army
   refills its ammunition at a quarter of the normal rate ("shell hunger"), which is world news and costs a little war support; an air raid spends one
   bomb load, without one it flies with unguided bombs (half the damage, easier to shoot down). Friends ship shells; AI orders early and holds raids back.
   Counter-play: make the enemy fight every month, hit his factories and power (production halves), order before the war, ask friends. */
const GMIL_STK2={US:[20,30,13,30,40,12],RU:[25,60,30,6,12,28],CN:[70,80,30,20,24,10],IL:[7,12,3,6,12,2],IR:[14,20,5,1,3,1],UA:[4,10,3,1,3,0],KP:[40,60,12,0,1,0],IN:[22,30,4,3,6,2],
  PK:[10,15,2,2,4,1],SA:[7,10,1,5,8,0],AE:[4,6,0,4,6,0],TR:[10,15,4,3,6,2],EG:[14,20,2,2,4,0],FR:[3,6,3,2,4,1],DE:[5,12,8,1,3,1],PL:[6,10,4,1,3,0],GB:[2,5,2,2,4,1],
  JP:[6,8,1,2,4,1],KR:[35,40,15,3,6,2],RS:[2,4,1,0,0,0],DW:[3,4,1,0,0,0],RV:[2,3,1,0,0,0],OB:[1,2,1,0,0,0],BI:[1,2,1,0,0,0]},GMIL_STK2_D=[3,5,1,1,2,0];
const GMIL_SK={ms:[0,0],ic:[0,3],sh:[1,0],pb:[1,3]},GMIL_SKK=['ms','ic','sh','pb'],GMIL_SH_BURN=25,GMIL_SH_DRY=.25;
const GMIL_ORD={ms:{n:1,cost:GMIL_MISSILE_COST,lead:4,nm:'missile salvo'},ic:{n:4,cost:600,lead:6,nm:'interceptor loads'},sh:{n:4,cost:400,lead:3,nm:'shell loads'},pb:{n:2,cost:300,lead:4,nm:'precision bomb loads'}},GMIL_ORD_MAX=3,GMIL_IC_NEED={m:2,a:1};
function gmilStkAt(c,k,j){const s=GMIL_SK[k]||GMIL_SK.ms;return (s[0]?(GMIL_STK2[c]||GMIL_STK2_D):gmilStkRow(c))[s[1]+j];}
function gmilStkNm(k,n){return n+' '+(k==='ms'?'missile salvo'+(n>1?'s':''):k==='ic'?'interceptor loads':k==='sh'?'shell load'+(n>1?'s':''):'precision bomb load'+(n>1?'s':''));}
function gmilStkRow(c){return GMIL_STK[c]||GMIL_STK_D;}
function gmilStkMax(c,k){return gmilStkAt(c,k,1);}
function gmilStkYr(c,k){return gmilStkAt(c,k,2);}
function gmilNew(){return {g:{},gid:1,fr:[],fid:1,zm:{},fq:[],n:{},bk:{},foe:'',nx:{}};}
function gmilN(c){const M=GC.mil,q=M.n[c]||(M.n[c]={ms:gmilStkRow(c)[0],so:[],dr:0});if(q.ic===undefined){q.ic=gmilStkRow(c)[3];q.oq=[];q.pa=[0,0];}if(q.sh===undefined){q.sh=gmilStkAt(c,'sh',0);q.pb=gmilStkAt(c,'pb',0);q.pa[2]=0;q.pa[3]=0;q.sa=0;}return q;}   // older saves get their interceptors on first use
function gmilDrStock(c){return GC.mil?gmilN(c).dr|0:0;}
function gmilKm(a,b){return Math.round(grDist(a,b)*GMIL_KMU);}
function gmilCul(c){return GMIL_CUL[c]||GMIL_REGCUL[(grNat(c)||{}).reg]||'en';}
function gmilName(c,R){if(typeof pplGenName==='function')return pplGenName(c,R);const L=GMIL_NM[gmilCul(c)]||GMIL_NM.en;return L[0][Math.floor(R()*L[0].length)]+' '+L[1][Math.floor(R()*L[1].length)];}
function gmilRng(a,b){return grRng(((GC.seed*131+GC.turn*17+(a|0)*7+(b|0))|0));}
function gmilGen(a){return a&&a.gid&&GC.mil?GC.mil.g[a.gid]||null:null;}
function gmilLv(g){let l=0;while(l<4&&g.xp>=GMIL_LVN[l])l++;return l;}
function gmilTitle(g){if(typeof pplRank==='function')return pplRank(g.o,g.lv);return ['Colonel','Brigadier','Major General','Lieutenant General','General'][g.lv|0];}
function gmilMaxGens(c){const n=GCM.P.filter(p=>p.land&&GC.prov[p.i].o===c).length;return Math.min(6,2+Math.floor(n/5));}
function gmilIsNaval(k){return GMIL_NAVAL.includes(k);}

// ---------- setup ----------
function gmilEnsure(){if(!GC)return;if(!GC.mil){GC.mil=gmilNew();gmilStartFleets();gmilGenStep(true);}
  for(const c of Object.keys(GC.nat))gmilN(c);
  if(!GC.mil.dr0){GC.mil.dr0=1;try{gmilDrInit();}catch(e){console.error('gmilDrInit',e);}}}
function gmilDrInit(){for(const c of GMIL_DRN){const N=GC.nat[c];if(!N||N.dead)continue;gmilN(c).dr=GMIL_DR0[c]||4;
    if(GMIL_DR0[c]&&N.cap>=0&&GCM.P[N.cap]&&!geCount(N.cap,'dsite'))geBl(N.cap).push(['dsite',0]);}}
function gmilStartFleets(){const P=GCM.P;for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c],nt=grNat(c),fac=nt.fac;const ports=P.filter(p=>p.land&&GC.prov[p.i].o===c&&p.port);if(!ports.length)continue;
    const V=GR_VBASE*(nt.major?1:.5)*(GC.len==='quick'?.7:1)*.10,us=[];
    for(const [k,w] of GMIL_FLEET){if(!grHasKind(fac,k))continue;const n=Math.max(k==='ship'?1:0,Math.round(V*w/grCost(fac,k)));for(let i=0;i<n;i++)us.push([k,100,0,100]);}
    if(!us.length)continue;const home=ports.find(p=>p.i===N.cap)||ports.sort((a,b)=>b.dev-a.dev||a.i-b.i)[0],z=gmilZoneOf(home.i);if(z<0)continue;
    const a=grAddArmy(c,z,us,'1st Fleet');a.fl=1;}}
function gmilZoneOf(pi){const s=GCM.P[pi].adj.filter(j=>GCM.P[j].sea).sort((a,b)=>GCM.P[a].cost-GCM.P[b].cost||a-b);return s.length?s[0]:-1;}

// ---------- generals ----------
function gmilGenStep(init){const M=GC.mil;for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead)continue;
    const mine=GC.armies.filter(a=>a.o===c&&!a.fl&&a.u.length).sort((x,y)=>grArmyVal(y)-grArmyVal(x)||x.id-y.id);
    const gens=Object.values(M.g).filter(g=>g.o===c&&!g.st).sort((x,y)=>x.id-y.id);
    for(const g of gens)if(g.aid&&!GC.armies.some(a=>a.id===g.aid&&a.gid===g.id)){g.aid=0;}   // army gone without the hook (safety)
    for(const a of mine){if(a.gid&&M.g[a.gid]&&!M.g[a.gid].st)continue;a.gid=0;if(grArmyVal(a)<4000)continue;
      let g=gens.find(x=>!x.aid&&!x.res);   /* a general the player put in reserve stays there */
      if(!g&&gens.length<gmilMaxGens(c)&&(init?gens.length<2:(M.nx[c]|0)<=GC.turn)){const R=gmilRng(M.gid,c.charCodeAt(0)*3+c.charCodeAt(1));g={id:M.gid++,o:c,nm:gmilName(c,R),tr:Math.floor(R()*4),xp:init?0:15,lv:0,st:0,aid:0,by:''};g.lv=gmilLv(g);M.g[g.id]=g;gens.push(g);M.nx[c]=GC.turn+2;
        if(!init&&c===GC.me)grLog(gmilTitle(g)+' '+g.nm+' ('+GMIL_TR[g.tr][0]+') takes command of '+a.nm+'.',c);}
      if(g){g.aid=a.id;a.gid=g.id;}}}}
/* Abdullah 2026-11-07 20:32 "should be able to assign a general to an army": move a general to one of your land armies (the army's
   current general swaps over to the general's old army, or returns to the pool), or hold him in reserve (aid 0). */
function gmilAssign(gid,aid){const M=GC&&GC.mil,g=M&&M.g[gid];if(!g||g.o!==GC.me||g.st)return;const old=g.aid&&GC.armies.find(x=>x.id===g.aid);
  if(!aid){if(old&&old.gid===g.id)old.gid=0;g.aid=0;g.res=1;return;}
  const a=GC.armies.find(x=>x.id===aid);if(!a||a.o!==GC.me||a.fl||a===old)return;const prev=a.gid&&M.g[a.gid]&&M.g[a.gid]!==g?M.g[a.gid]:null;
  if(old&&old.gid===g.id)old.gid=0;if(prev){prev.aid=0;prev.res=0;if(old){old.gid=prev.id;prev.aid=old.id;}}
  a.gid=g.id;g.aid=a.id;g.res=0;grLog(gmilTitle(g)+' '+g.nm+' takes command of '+a.nm+'.',GC.me);}
function gmilMerge(a,b){if(!b.gid)return;const M=GC.mil,gb=M.g[b.gid];b.gid=0;if(!gb)return;if(!a.gid){a.gid=gb.id;gb.aid=a.id;return;}
  const ga=M.g[a.gid];if(ga&&gb.xp>ga.xp){ga.aid=0;a.gid=gb.id;gb.aid=a.id;}else gb.aid=0;}   // the other one goes back to the pool
function gmilLost(a){const M=GC.mil;if(!M||!a.gid)return;const g=M.g[a.gid];a.gid=0;if(!g||g.st)return;g.aid=0;const R=gmilRng(g.id,a.id),r=R(),foe=M.foe;
  const me=g.o===GC.me||foe===GC.me,nm=gmilTitle(g)+' '+g.nm;
  if(r<.4){g.st=1;grLog(nm+' fell with '+a.nm+'.',me?GC.me:g.o);}
  else if(r<.7&&foe&&foe!==g.o){g.st=2;g.by=foe;const ran=300+100*(g.lv|0);if(GC.nat[foe]){GC.nat[foe].cash+=ran;}grLog(nm+' ('+GCM.nats.get(g.o).name+') was captured by '+GCM.nats.get(foe).name+'. Ransom value $'+ran+'.',me?GC.me:g.o);}
  else{g.xp=Math.floor(g.xp*.8);grLog(nm+' escaped the rout.',me?GC.me:'');}}
function gmilMul(a,def){const g=gmilGen(a);if(!g)return 1;let m=1+.025*g.lv;
  if(a.fl)return m;let tk=0,inf=0,n=Math.max(1,a.u.length);for(const r of a.u){if(r[0]==='tank'||r[0]==='heli'||r[0]==='champ')tk++;else if(r[0]==='inf'||r[0]==='at')inf++;}
  if(g.tr===0)m+=.10*tk/n;else if(g.tr===1)m+=def?.06:0;else if(g.tr===2)m+=.04;else m+=.10*inf/n;return m;}
function gmilBattle(b,win){const M=GC.mil;if(!M)return;for(const side of ['att','def']){const won=side===win;for(const id of (side==='att'?b.att:b.def)){const a=GC.armies.find(x=>x.id===id),g=gmilGen(a);if(!g)continue;
      g.xp+=(won?36:12)+(g.tr===3&&won?6:0)+(g.tr===1&&side==='def'?6:0);const L=gmilLv(g);if(L>g.lv){g.lv=L;if(g.o===GC.me)grLog(gmilTitle(g)+' '+g.nm+' reached level '+L+'.',g.o);}
      if(g.tr===3&&won&&a.u.length>2){for(const r of a.u)r[1]=Math.min(100,r[1]+3);}}}}
// the hero squad that stands for the general in a Fight-it battle: the perk table the battle applies to that side's units
function gmilPerk(L){let best=null;for(const s of L){const g=gmilGen(s.arr);if(g&&(!best||g.lv>best.lv))best={tr:g.tr,lv:g.lv,nm:gmilTitle(g)+' '+g.nm,gid:g.id};}return best;}
function gmilApplyPerks(gr,gp){if(!gp)return;for(let t=0;t<2;t++){const p=gp[t];if(!p)continue;const defend=gr.att!==t;
    for(const [rec,u,team] of gr.ents){if(team!==t||u.dead)continue;let m=1+.03*p.lv;const k=rec[0];
      if(p.tr===0&&(k==='tank'||k==='heli'||k==='champ'))m+=.10;else if(p.tr===1&&defend)m+=.09;else if(p.tr===3&&(k==='inf'||k==='at'||k==='aa'))m+=.10;
      if(p.tr===2){if(u.s&&u.s.ammo)u.ammo=u.s.ammo;}
      if(m!==1){u.max=Math.round(u.max*m);u.hp=Math.min(u.max,Math.round(u.hp*m));}}}}
function gmilHeroFell(gid){const M=GC.mil,g=M&&M.g[gid];if(!g||g.st)return;g.xp=Math.floor(g.xp*.85);const R=gmilRng(g.id,77);if(R()<.35){g.st=1;g.aid=0;const a=GC.armies.find(x=>x.gid===g.id);if(a)a.gid=0;grLog(gmilTitle(g)+' '+g.nm+' was killed leading the battle.',g.o);}}

// ---------- fleets ----------
function gmilFleets(c){return GC.armies.filter(a=>a.fl&&a.o===c&&a.u.length);}
function gmilHasPort(pi){const p=GCM.P[pi];return p.land&&(p.port||geCount(pi,'port')>0);}
function gmilBuyFleet(c,pi,k){const N=GC.nat[c],st=GC.prov[pi],p=GCM.P[pi];if(!st||st.o!==c)return 'Not your province.';if(!gmilHasPort(pi))return 'Needs a port.';
  const fac=grNat(c).fac,rc=GMIL_BUY.find(r=>r[0]===k);if(!rc||!grHasKind(fac,k))return 'Not available to your nation.';if(gmilZoneOf(pi)<0)return 'No sea access.';
  const cost=grCost(fac,k)*rc[1],man=2*rc[1];if(N.cash<cost)return 'Not enough money.';if(N.e&&N.e.man<man)return 'Not enough manpower.';
  N.cash-=cost;if(N.e)N.e.man-=man;GC.mil.fq.push({o:c,pi,t:GC.turn+2,k,n:rc[1]});return '';}
function gmilFleetArrive(){const M=GC.mil,keep=[];for(const q of M.fq){if(q.t>GC.turn){keep.push(q);continue;}if(GC.nat[q.o].dead||GC.prov[q.pi].o!==q.o)continue;const z=gmilZoneOf(q.pi);if(z<0)continue;
    let f=GC.armies.find(a=>a.fl&&a.o===q.o&&a.at===z&&!a.path.length);const us=[];for(let i=0;i<q.n;i++)us.push([q.k,100,0,100]);
    if(f)f.u.push(...us);else{f=grAddArmy(q.o,z,us,(GC.nat[q.o].an)+(GC.nat[q.o].an===1?'st':GC.nat[q.o].an===2?'nd':GC.nat[q.o].an===3?'rd':'th')+' Fleet');f.fl=1;}
    if(q.o===GC.me)grLog(q.n+'× '+grKindName(grNat(q.o).fac,q.k)+' joined the fleet at '+GCM.P[z].n+'.',q.o);}M.fq=keep;}
function gmilFleetRetreat(a,from){const P=GCM.P;let best=-1,bs=-1e9;for(const j of P[from].adj){if(!P[j].sea)continue;if(GC.armies.some(x=>x.at===j&&x.fl&&grAtWar(x.o,a.o)))continue;
    const home=GC.nat[a.o].cap>=0?grDist(j,GC.nat[a.o].cap):0;const s=-home*.01+(j===a.from?4:0)+(P[j].adj.some(k=>P[k].land&&GC.prov[k].o===a.o&&gmilHasPort(k))?6:0);if(s>bs){bs=s;best=j;}}return best;}
function gmilSeaDenied(a,nx){if(a.fl||!GCM.P[nx].sea)return false;let foe=false,fr=false;for(const x of GC.armies){if(x.at!==nx||!x.fl||!x.u.length)continue;if(x.o===a.o)fr=true;else if(grAtWar(x.o,a.o))foe=true;}return foe&&!fr;}
function gmilSeaHostile(p,here){return here.some(a=>a.fl)&&here.some(a=>here.some(b=>b.o!==a.o&&grAtWar(a.o,b.o)));}
// sea battles: defender value bonus = hidden subs (cut by patrol boats), home waters
function gmilSeaDef(b){let m=1.0;const D=grSideUnits(b,'def'),A=grSideUnits(b,'att');let sub=0,all=0;for(const s of D)for(const r of s.u){all++;if(r[0]==='sub')sub++;}
  let asw=0;for(const s of A)for(const r of s.u)if(r[0]==='boat'||r[0]==='fast')asw++;if(all)m+=.25*sub/all*(asw>=2?.35:1);
  const p=GCM.P[b.p];if(p.adj.some(k=>GCM.P[k].land&&GC.prov[k].o===b.dn&&gmilHasPort(k)))m+=.06;return m;}
function gmilBlockRefresh(){const M=GC.mil;if(!M)return;M.bk={};for(const p of GCM.P){if(!p.land||!gmilHasPort(p.i))continue;const o=GC.prov[p.i].o;
    for(const j of p.adj){if(!GCM.P[j].sea)continue;let foe=false,fr=false;for(const a of GC.armies){if(a.at!==j||!a.fl||!a.u.length)continue;if(a.o===o)fr=true;else if(grAtWar(a.o,o))foe=true;}
      if(foe&&!fr){M.bk[p.i]=1;break;}}}}
function gmilBk(pi){const M=GC.mil;return !!(M&&M.bk&&M.bk[pi]);}
function gmilMines(a){const M=GC.mil;const p=GCM.P[a.at];if(!p.sea||!a.fl)return 'Fleets only, at sea.';if(!a.u.some(r=>r[0]==='minel'))return 'Needs a minelayer.';a.mine=a.mine?0:1;return '';}
function gmilSeaStep(){const M=GC.mil,R=grRng(GC.seed*43+GC.turn*5);
  for(const a of GC.armies.slice().sort((x,y)=>x.id-y.id)){const p=GCM.P[a.at];if(!p.sea||!a.u.length)continue;
    if(a.fl&&a.mine&&!a.path.length&&a.u.some(r=>r[0]==='minel')){const z=M.zm[a.at];if(!z||z.o===a.o){M.zm[a.at]={o:a.o,n:Math.min(8,(z?z.n:0)+2)};}else z.n=Math.max(0,z.n-2);}
    const z=M.zm[a.at];if(z&&z.n>0&&z.o!==a.o&&grAtWar(z.o,a.o)){const sw=a.u.filter(r=>r[0]==='sweep').length;if(sw){z.n=Math.max(0,z.n-2*sw);if(a.o===GC.me)grLog('Minesweepers cleared mines at '+p.n+'.',a.o);continue;}
      let hits=Math.floor(z.n/3)+(R()<(z.n%3)/3?1:0);hits=Math.min(hits,2,a.u.length);
      for(let i=0;i<hits;i++){let w=0;for(let j=1;j<a.u.length;j++)if(a.u[j][1]<a.u[w][1])w=j;a.u[w][1]-=35;if(a.u[w][1]<=8)a.u.splice(w,1);z.n--;}
      if(hits)grLog(a.nm+' ('+GCM.nats.get(a.o).name+') hit mines at '+p.n+'.',a.o===GC.me||z.o===GC.me?GC.me:a.o);}}
  for(const k of Object.keys(M.zm))if(M.zm[k].n<=0)delete M.zm[k];
  for(const a of GC.armies.slice())if(!a.u.length)grDrop(a);}

// ---------- map strikes ----------
function gmilSites(c,pi,rng,type){const P=GCM.P;let best=-1,bd=1e9;
  for(const p of P){if(!p.land||GC.prov[p.i].o!==c)continue;const ok=type==='d'?(geEff(p.i,'dsite')>0||GC.armies.some(a=>a.o===c&&a.at===p.i&&!a.fl&&a.u.length&&(a.ln|0)>0)):type==='a'?geEff(p.i,'airfield')>0:(geCount(p.i,'base')+geCount(p.i,'airfield')>0||p.cap);
    if(!ok)continue;const d=grDist(p.i,pi);if(d<=rng&&d<bd){bd=d;best=p.i;}}return best;}
function gmilStrikeCheck(c,type,pi,k,n){const N=GC.nat[c],E=N.e,S=GMIL_ST[type],M=gmilN(c),p=GCM.P[pi];if(!S||!p)return 'Unknown strike.';if(M.so.length>=3)return 'Three strikes a month at most.';
  if(M.so.some(o=>o.t===type&&o.pi===pi&&o.k===k&&(o.n|0)===(type==='d'?(n|0)||Math.min(GMIL_SALVO,M.dr|0):0)))return 'Already ordered.';
  if(p.land){const o=GC.prov[pi].o;if(o===c||!grAtWar(c,o))return 'Only at nations you are at war with.';if(k==='f')return 'Fleets are at sea.';}
  else{if(k!=='f')return 'Only fleets at sea.';if(!GC.armies.some(a=>a.at===pi&&a.fl&&grAtWar(a.o,c)))return 'No enemy fleet there.';}
  if(type==='d'&&(M.dr|0)<1)return 'No one-way drones in stock (launch sites and War Factories make them).';
  if(type==='m'&&M.ms<1)return 'No missiles in stock (Military → Stockpiles: order more, or ask an ally).';
  if(gmilSites(c,pi,S.rng,type)<0)return type==='a'?'No airfield in range.':type==='d'?'No launch site or launcher truck within ~2,000 km.':'No launch site in range.';
  if(type!=='m'){if(N.cash<S.cost)return 'Costs $'+S.cost+'.';if(E&&(E.dry||E.fuel<S.fuel+1))return 'Not enough fuel.';if(type==='a'&&geSortieStock(c,pi,S.rng)<2)return 'Not enough sorties (fuel or airfields).';}
  return '';}
function gmilStrike(c,type,pi,k,n){const e=gmilStrikeCheck(c,type,pi,k,n);if(e)return e;const N=GC.nat[c],S=GMIL_ST[type],M=gmilN(c);
  if(type==='d'){n=Math.min(M.dr|0,Math.max(1,n|0||GMIL_SALVO));M.dr-=n;M.so.push({t:type,pi,k,n});return '';}
  if(type==='m'){M.ms--;M.so.push({t:type,pi,k});return '';}N.cash-=S.cost;if(N.e)N.e.fuel-=S.fuel;const pb=M.pb>0?1:0;M.pb-=pb;M.so.push({t:type,pi,k,pb});return '';}   // an air raid spends one precision bomb load; without one it flies with unguided bombs
// launcher trucks: a mobile launcher joins an army in a province with a launch site or War Factory
function gmilBuyLauncher(c,aid){const N=GC.nat[c],a=GC.armies.find(x=>x.id===aid&&x.o===c&&!x.fl);if(!a||!a.u.length)return 'Pick one of your armies.';if(!GMIL_DRN.includes(c))return 'Your nation does not field long-range one-way drones.';
  if(!(geEff(a.at,'dsite')>0||geEff(a.at,'factory')>0))return 'Needs a launch site or War Factory in the same province.';if((a.ln|0)>=GMIL_LN_MAX)return 'That army carries '+GMIL_LN_MAX+' launchers already.';if(N.cash<GMIL_LN_COST)return 'Costs $'+GMIL_LN_COST+'.';N.cash-=GMIL_LN_COST;a.ln=(a.ln|0)+1;return '';}
// a launcher is hidden unless spotted: it fired recently (launch signature), or enemy ground forces are in or next to its province
function gmilLnExposed(a){if((a.lx|0)>=GC.turn-1)return true;const P=GCM.P[a.at];if(!P)return false;return GC.armies.some(x=>!x.fl&&x.u.length&&x.o!==a.o&&grAtWar(x.o,a.o)&&(x.at===a.at||P.adj.includes(x.at)));}
function gmilDrMonth(){for(const c of GMIL_DRN){const N=GC.nat[c];if(!N||N.dead)continue;const M=gmilN(c);let mk=0;for(const p of GCM.P){if(!p.land||GC.prov[p.i].o!==c)continue;mk+=Math.round(6*geEff(p.i,'dsite'))+Math.min(1,Math.round(geEff(p.i,'factory')));}
    if(N.e&&(N.e.dry||N.e.pw<.5))mk=Math.floor(mk/2);mk=Math.min(mk,GMIL_DR_MAX-(M.dr|0),Math.floor(Math.max(0,N.cash)/GMIL_DR_COST));if(mk>0){M.dr=(M.dr|0)+mk;N.cash-=mk*GMIL_DR_COST;}}}
// grand-map Fight-it: drones a side can call = its stock, only if a launch site or launcher is within ~2,000 km of the battle
function gmilDrAvail(c,pi){if(!GC||!GC.mil||!GMIL_DRN.includes(c))return 0;return gmilSites(c,pi,GMIL_ST.d.rng,'d')>=0?gmilDrStock(c):0;}
function gmilDrBattleDone(gr,n0,n1){if(!gr||!gr.du)return;[n0,n1].forEach((c,t)=>{if(c&&gr.du[t]&&GC.mil){const M=gmilN(c);M.dr=Math.max(0,(M.dr|0)-gr.du[t]);}});}
// stock orders: paid now, delivered months later (real lead times are years; the campaign compresses them, the order of magnitude between nations is real)
function gmilOrdLead(c,k){return GMIL_ORD[k].lead+(gmilStkYr(c,k)>0?0:2);}
function gmilOrderCheck(c,k){const N=GC.nat[c],M=gmilN(c),O=GMIL_ORD[k];if(!O)return 'Unknown order.';if(gmilStkYr(c,k)<=0&&typeof unSanctioned==='function'&&unSanctioned(c))return 'Under UN sanctions nobody sells you these.';
  const open=M.oq.filter(o=>o.k===k&&!o.by).length;if(open>=GMIL_ORD_MAX)return 'The production lines are full ('+GMIL_ORD_MAX+' orders running).';if(M[k]+open*O.n>=gmilStkMax(c,k))return 'Depots are full.';if(N.cash<O.cost)return 'Costs $'+O.cost+'.';return '';}
function gmilOrder(c,k){const e=gmilOrderCheck(c,k);if(e)return e;const O=GMIL_ORD[k];GC.nat[c].cash-=O.cost;gmilN(c).oq.push({k,n:O.n,t:GC.turn+gmilOrdLead(c,k)});return '';}
// ship stock to an ally or close friend: arrives next month; every nation at war with the receiver resents the sender
function gmilSendN(k){return k==='ms'||k==='pb'?1:2;}
function gmilSendCheck(c,to,k){if(!GMIL_ORD[k]||!GC.nat[to]||GC.nat[to].dead||to===c)return 'Pick a nation.';if(grAtWar(c,to))return 'You are at war with them.';if(!grAllied(c,to)&&gdOp(c,to)<25)return 'Only to allies and close friends.';
  const M=gmilN(c);if(M[k]<gmilSendN(k))return 'Nothing to spare.';if((M.sent|0)>=GC.turn)return 'One shipment a month.';return '';}
function gmilSend(c,to,k){const e=gmilSendCheck(c,to,k);if(e)return e;const M=gmilN(c),n=gmilSendN(k);M[k]-=n;M.sent=GC.turn;gmilN(to).oq.push({k,n,t:GC.turn+1,by:c});gdRel(c,to,4);
  for(const w of Object.keys(GC.war).sort()){const ab=w.split('|');if(!ab.includes(to))continue;const foe=ab.find(x=>x!==to);if(foe&&foe!==c&&GC.nat[foe]&&!GC.nat[foe].dead)gdRel(c,foe,k==='ms'?-12:-6);}
  grLog(GCM.nats.get(c).name+' ships '+gmilStkNm(k,n)+' to '+GCM.nats.get(to).name+'.','');return '';}
// shells: called once a month per army from the supply step (13g geSupplyStep). Fighting burns the national stock; an empty stock slows every refill.
function gmilShOut(c){grLog(GCM.nats.get(c).name+' is running out of artillery shells: its armies now refill ammunition at a quarter of the normal rate.','');
  if(typeof wsN==='function'){const W=wsN(c);if(W&&wsStyle(c)!=='zeal')W.wsE-=2;}}
function gmilShell(a,da){if(!GC.mil||a.fl||!GC.nat[a.o])return da;const M=gmilN(a.o);
  if(a.fo===GC.turn&&a.u.length&&M.sh>0){M.sa=(M.sa|0)+a.u.length*GMIL_SH_BURN;while(M.sa>=1000&&M.sh>0){M.sa-=1000;M.sh--;}if(M.sh<=0){M.sh=0;M.sa=0;gmilShOut(a.o);}}
  return M.sh<=0&&da>0?da*GMIL_SH_DRY:da;}
function gmilIcOut(c){grLog(GCM.nats.get(c).name+' has run out of air-defence interceptors: what flies in now gets through.','');
  if(typeof wsN==='function'){const W=wsN(c);if(W)W.wsE-=wsStyle(c)==='zeal'?1:4;}}   // the one war-support meter (13v): people feel exposed; Zealous nations shrug most of it off
function gmilStockMonth(){for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead)continue;const M=gmilN(c),slow=N.e&&(N.e.dry||N.e.pw<.5)?2:1;
    GMIL_SKK.forEach((k,i)=>{const mx=gmilStkMax(c,k);M.pa[i]=(M.pa[i]|0)+Math.round(gmilStkYr(c,k)*1000/12/slow);while(M.pa[i]>=1000){M.pa[i]-=1000;if(M[k]<mx)M[k]++;}if(M[k]>=mx)M.pa[i]=0;});
    const due=M.oq.filter(o=>o.t<=GC.turn);if(!due.length)continue;M.oq=M.oq.filter(o=>o.t>GC.turn);
    for(const o of due){M[o.k]+=o.n;if(c===GC.me)grLog((o.by?GCM.nats.get(o.by).name+' delivered ':'Delivered from the factories: ')+gmilStkNm(o.k,o.n)+'.',c);}}}
function gmilAIStock(c,R){const N=GC.nat[c],Q=gmilN(c),war=Object.keys(GC.war).some(k=>k.split('|').includes(c));
  if(Q.ic<gmilStkMax(c,'ic')*(war?.6:.35)&&N.cash>(war?1500:4000)&&!Q.oq.some(o=>o.k==='ic'&&!o.by)&&(war||R()<.15))gmilOrder(c,'ic');
  if(war&&Q.ms<2&&N.cash>2200&&!Q.oq.some(o=>o.k==='ms'&&!o.by))gmilOrder(c,'ms');
  if(Q.sh<gmilStkMax(c,'sh')*(war?.5:.3)&&N.cash>(war?1200:3500)&&!Q.oq.some(o=>o.k==='sh'&&!o.by)&&(war||R()<.15))gmilOrder(c,'sh');
  if(war&&Q.pb<1&&gmilStkMax(c,'pb')>0&&N.cash>1800&&!Q.oq.some(o=>o.k==='pb'&&!o.by))gmilOrder(c,'pb');
  // a friend at war whose guns have fallen silent: a nation at peace with full depots sometimes ships shells (allies and close friends, as in real wars)
  if(!war&&Q.sh>gmilStkMax(c,'sh')*.6&&Q.sh>=6&&R()<.25){const fr=Object.keys(GC.nat).sort().find(x=>x!==c&&!GC.nat[x].dead&&!grAtWar(c,x)&&(grAllied(c,x)||gdOp(c,x)>=25)&&gmilN(x).sh<=0&&Object.keys(GC.war).some(k=>k.split('|').includes(x)));if(fr)gmilSend(c,fr,'sh');}
  // an ally under fire with empty launchers: a nation at peace with deep depots sometimes ships a little (real resupply is rare, slow and political)
  if(!war&&Q.ic>gmilStkMax(c,'ic')*.6&&R()<.2){const al=Object.keys(GC.nat).sort().find(x=>x!==c&&!GC.nat[x].dead&&grAllied(c,x)&&gmilStkMax(x,'ic')>2&&gmilN(x).ic<=1&&Object.keys(GC.war).some(k=>k.split('|').includes(x)));if(al)gmilSend(c,al,'ic');}}
function gmilAAUnits(pi){let n=0;const st=GC.prov[pi];if(st)for(const r of st.gar)if(r[0]==='aa')n++;for(const a of GC.armies)if(a.at===pi&&!a.fl)for(const r of a.u)if(r[0]==='aa')n++;return n;}
function gmilHit(L,hits,dmg){let got=0;for(let i=0;i<hits&&L.length;i++){let w=0;for(let j=1;j<L.length;j++)if(L[j][1]>L[w][1])w=j;   // the healthiest unit is the most exposed one first: spreads damage
    L[w][1]-=dmg;got++;if(L[w][1]<=8)L.splice(w,1);}return got;}
function gmilStrikes(){const M=GC.mil;if(!M)return;const R=grRng(GC.seed*53+GC.turn*9);
  for(const c of Object.keys(GC.nat).sort()){const Q=gmilN(c);const ord=Q.so;Q.so=[];if(GC.nat[c].dead)continue;
    for(const o of ord){const p=GCM.P[o.pi],S=GMIL_ST[o.t];if(!p)continue;const cn=GCM.nats.get(c).name,vis=c===GC.me;
      const tgtO=p.land?GC.prov[o.pi].o:'';if(p.land&&(tgtO===c||!grAtWar(c,tgtO)))continue;if(p.land&&o.k==='b'&&typeof gescWar==='function')gescWar(c,tgtO,6);   // strikes on industry and cities: the war climbs to 'Strategic strikes' (first crosser pays)
      const raw=o.t==='a'?Math.min(4,Math.floor(geSortieStock(c,o.pi,S.rng)/1)||2):o.t==='d'?Math.max(1,o.n|0):1;
      let aaB=p.land?geCount(o.pi,'aa'):0,aaU=p.land?gmilAAUnits(o.pi):0;if(!p.land)for(const a of GC.armies)if(a.at===o.pi&&a.fl&&grAtWar(a.o,c))for(const r of a.u)if(r[0]==='ship'||r[0]==='boat')aaU+=.5;
      const ung=o.t==='a'&&o.pb===0,dmg=Math.round(S.dmg*(ung?.5:1));let ic=Math.min(.8,(.26*aaB+.03*aaU)*S.ic*(ung?1.3:1)),surv=0,site=-1,dkm=0,dry=0;const DQ=p.land&&GC.nat[tgtO]?gmilN(tgtO):null,ic0=DQ?DQ.ic:0;   // the defender's interceptor stock
      if(o.t==='d'){   // one-way drones: each defence battery engages only so many per salvo, so big salvos saturate it (~185 km/h, hours of flight)
        site=gmilSites(c,o.pi,S.rng,'d');dkm=site>=0?gmilKm(site,o.pi):0;const cap0=Math.round(6*aaB+1.5*aaU),cap=DQ?Math.min(cap0,DQ.ic*4):cap0,pk=aaB+aaU>0?Math.min(.8,.5+.1*aaB):0;if(Math.min(raw,cap0)>cap)dry=1;
        for(let i=0;i<raw;i++)if(!(i<cap&&R()<pk))surv++;if(DQ&&pk>0)DQ.ic-=Math.ceil(Math.min(raw,cap)/4);
        for(const a of GC.armies)if(a.o===c&&a.at===site&&(a.ln|0)>0)a.lx=GC.turn;}   // a launch is seen: the launcher is exposed for a month
      else for(let i=0;i<raw;i++){const need=GMIL_IC_NEED[o.t];if(DQ&&ic>0&&DQ.ic<need){dry=1;R();surv++;}else{if(DQ&&ic>0)DQ.ic-=need;if(R()>=ic)surv++;}}
      if(DQ&&ic0>0&&DQ.ic<=0){DQ.ic=0;gmilIcOut(tgtO);}
      const tn=p.land?GCM.nats.get(tgtO).name:'the enemy fleet',inv=(vis||tgtO===GC.me)?GC.me:c;
      if(!surv){grLog(cn+' '+(o.t==='d'?raw+' one-way drones':S.n.toLowerCase())+' on '+p.n+' were intercepted'+(aaB?' by air defense':'')+'.',inv);continue;}
      let msg='';
      if(o.k==='b'&&p.land){const bl=geBl(o.pi),tg=bl.filter(r=>['factory','refinery','power','port','airfield','mine','base','aa','fort','dsite'].includes(r[0]));
        if(!tg.length){const n=gmilHit(GC.prov[o.pi].gar,surv,dmg*1.5);msg='hit the garrison ('+n+' units struck)';}
        else{let names=[];for(let i=0;i<surv;i++){const r=tg[Math.floor(R()*tg.length)];r[1]=Math.min(100,(r[1]|0)+dmg);if(!names.includes(r[0]))names.push(r[0]);}
          msg='damaged '+names.map(k=>GE_B[k]?GE_B[k][0].toLowerCase():k).join(', ');GC.prov[o.pi].lt=GC.turn+2;}}
      else if(o.k==='a'&&p.land){let tot=0;const arm=GC.armies.filter(a=>a.at===o.pi&&!a.fl&&grAtWar(c,a.o)&&a.u.length).sort((x,y)=>x.id-y.id);
        for(const a of arm)tot+=gmilHit(a.u,Math.ceil(surv/arm.length),dmg*(o.t==='m'?1.4:1));tot+=gmilHit(GC.prov[o.pi].gar,surv-Math.min(surv,tot)>0?1:0,dmg);msg='struck '+(arm.length?arm.length+' army(ies)':'the garrison');for(const a of arm)if((a.ln|0)>0&&gmilLnExposed(a)){const l=Math.min(a.ln,Math.ceil(surv/8));a.ln-=l;msg+=' (destroyed '+l+' launcher'+(l>1?'s':'')+')';}}
      else if(!p.land){const fl=GC.armies.filter(a=>a.at===o.pi&&grAtWar(c,a.o)&&a.u.length).sort((x,y)=>(y.fl|0)-(x.fl|0)||x.id-y.id);let n=0;for(const a of fl)n+=gmilHit(a.u,Math.ceil(surv/fl.length),dmg*(o.t==='m'?1.6:1));msg='hit '+fl.length+' fleet(s) at sea';}
      else continue;
      grLog(cn+' '+(o.t==='d'?raw+' one-way drones ('+dkm+' km, ~'+Math.round(dkm/GMIL_DKMH)+' h flight)':S.n.toLowerCase()+(ung?' with unguided bombs':''))+' on '+p.n+' ('+tn+'): '+msg+(surv<raw?' ('+(raw-surv)+' shot down)':'')+(dry?' Air defense there is out of interceptors.':'')+'.',inv);}}
  for(const a of GC.armies.slice())if(!a.u.length)grDrop(a);}

// ---------- front lines ----------
function gmilFronts(c){return GC.mil.fr.filter(f=>f.o===c);}
function gmilFrontOf(a){return a.fr?GC.mil.fr.find(f=>f.id===a.fr)||null:null;}
function gmilAddFront(c,foe){let f=GC.mil.fr.find(x=>x.o===c&&x.foe===foe);if(f)return f;f={id:GC.mil.fid++,o:c,foe,ord:'hold'};GC.mil.fr.push(f);return f;}
function gmilLine(f){const P=GCM.P;return P.filter(p=>p.land&&GC.prov[p.i].o===f.o&&p.adj.some(j=>P[j].land&&GC.prov[j].o===f.foe));}
function gmilEnemyAt(foe,j){return GC.prov[j].o===foe?grProvDef(j)+GC.armies.filter(x=>x.at===j&&x.o===foe&&!x.fl).reduce((s,x)=>s+grArmyVal(x),0):0;}
function gmilAssign(aid,fid){const a=GC.armies.find(x=>x.id===aid);if(!a||a.fl)return 'Armies only.';if(!fid){a.fr=0;return '';}const f=GC.mil.fr.find(x=>x.id===fid);if(!f||f.o!==a.o)return 'No such front.';a.fr=fid;return '';}
function gmilPlanFront(f,plan){const P=GCM.P,c=f.o,line=gmilLine(f);if(!line.length)return;const cap=GC.nat[c].cap,arms=GC.armies.filter(a=>a.fr===f.id&&a.o===c&&!a.fl&&!a.path.length&&a.u.length&&!(a.at===cap&&typeof grCapHeld==='function'&&grCapHeld(c,a)<grCapThreat(c)*1.2)).sort((x,y)=>x.id-y.id);   /* A-REAL: the capital's guard stays when it is threatened */
  const threat=pi=>{let t=0;for(const j of P[pi].adj)if(P[j].land&&GC.prov[j].o===f.foe)t+=gmilEnemyAt(f.foe,j)*.5;return t;};
  const defNow=pi=>grProvDef(pi)*.5+GC.armies.filter(x=>x.at===pi&&x.o===c&&!x.fl).reduce((s,x)=>s+grArmyVal(x),0)+(plan[pi]||0);
  for(const a of arms){const val=grArmyVal(a)*gmilMul(a,0);let tgt=-1,ts=-1e9;
    if(f.ord!=='hold'){   // push / counter-attack: weakest worthwhile enemy province within 3 hops of land
      const seen=new Set([a.at]);let fr=[a.at];for(let d=0;d<3&&fr.length;d++){const nx=[];for(const u of fr)for(const j of P[u].adj){if(seen.has(j)||!P[j].land)continue;seen.add(j);nx.push(j);if(GC.prov[j].o!==f.foe)continue;
          if(typeof grNukStop==='function'&&grNukStop(c,j,f.foe))continue;const def=gmilEnemyAt(f.foe,j)*1.25*(1+(typeof grDepth==='function'?grDepth(j,c,f.foe):0));let sc=(P[j].wg?40:0)+P[j].dev*4+(val/Math.max(300,def)-1)*30-d*8;
          if(f.ord==='counter'){sc+=GC.prov[j].o0===c?60:-15;}
          const need=f.ord==='counter'?1.0:1.12;if(def<val*need&&sc>ts){ts=sc;tgt=j;}}fr=nx;}}
    if(tgt>=0){const r=grPath(c,a.at,tgt);if(r&&!r.decl&&r.path.length){a.path=r.path;a.pg=0;plan[tgt]=(plan[tgt]||0)+val;continue;}}
    // hold: stand on the line province that needs men most
    const inLine=line.some(p=>p.i===a.at);let best=-1,bs=-1e9;for(const p of line){const s=threat(p.i)-defNow(p.i)*(p.i===a.at?.7:1)-(p.i===a.at?0:grDist(a.at,p.i)*.4);if(s>bs){bs=s;best=p.i;}}
    if(best>=0&&best!==a.at&&(!inLine||bs>threat(a.at)-defNow(a.at)*.7+400)){const r=grPath(c,a.at,best);if(r&&!r.decl&&r.path.length&&r.turns<=4){a.path=r.path;a.pg=0;}}
    plan[a.path.length?a.path[a.path.length-1]:a.at]=(plan[a.path.length?a.path[a.path.length-1]:a.at]||0)+val;}}
function gmilAIFronts(c){const N=GC.nat[c],P=GCM.P;const foes=Object.keys(GC.war).filter(k=>k.split('|').includes(c)).map(k=>k.split('|').find(x=>x!==c)).filter(x=>GC.nat[x]&&!GC.nat[x].dead).sort();
  for(const f of gmilFronts(c).slice())if(!foes.includes(f.foe)){GC.mil.fr.splice(GC.mil.fr.indexOf(f),1);for(const a of GC.armies)if(a.fr===f.id)a.fr=0;}
  const contact=foes.filter(x=>P.some(p=>p.land&&GC.prov[p.i].o===c&&p.adj.some(j=>P[j].land&&GC.prov[j].o===x))).slice(0,3);
  for(const x of contact)gmilAddFront(c,x);const fs=gmilFronts(c);if(!fs.length)return;
  for(const f of fs){const line=gmilLine(f);const mine=GC.armies.filter(a=>a.fr===f.id&&!a.fl).reduce((s,a)=>s+grArmyVal(a),0);let foeV=0;for(const p of line)for(const j of p.adj)if(P[j].land&&GC.prov[j].o===f.foe)foeV+=gmilEnemyAt(f.foe,j)*.5;
    const lost=P.some(p=>p.land&&GC.prov[p.i].o===f.foe&&GC.prov[p.i].o0===c);f.ord=mine>foeV*1.3?'push':lost?'counter':'hold';}
  const idle=GC.armies.filter(a=>a.o===c&&!a.fl&&!a.fr&&!a.path.length&&a.u.length&&grArmyVal(a)>=2500).sort((x,y)=>x.id-y.id);
  for(const a of idle){if(GC.nat[c].cap===a.at&&GC.armies.filter(x=>x.o===c&&x.at===a.at&&!x.fl).length===1&&idle.length>1)continue;
    let bf=null,bs=-1e9;for(const f of fs){const line=gmilLine(f);if(!line.length)continue;let s=0;for(const p of line)for(const j of p.adj)if(P[j].land&&GC.prov[j].o===f.foe)s+=P[j].dev;
      s-=GC.armies.filter(x=>x.fr===f.id).length*2;const near=Math.min(...line.map(p=>grDist(a.at,p.i)));s-=near*.05;if(s>bs){bs=s;bf=f;}}
    if(bf)a.fr=bf.id;}}

// ---------- AI fleets and strikes ----------
function gmilAIFleets(c,R){const N=GC.nat[c],P=GCM.P,fac=grNat(c).fac;const foes=Object.keys(GC.war).filter(k=>k.split('|').includes(c)).map(k=>k.split('|').find(x=>x!==c));
  const mine=gmilFleets(c).sort((x,y)=>x.id-y.id);
  for(const a of mine){if(a.path.length)continue;const val=grArmyVal(a);if(a.u.length>1&&mine.some(b=>b!==a&&b.at===a.at&&!b.path.length&&b.id<a.id)){grMerge(a.id);continue;}
    if(!foes.length)continue;let tgt=-1,ts=-1e9;
    const seen=new Set([a.at]);let fr=[a.at];for(let d=0;d<5&&fr.length;d++){const nx=[];for(const u of fr)for(const j of P[u].adj){if(seen.has(j)||!P[j].sea)continue;seen.add(j);nx.push(j);
        const en=GC.armies.filter(x=>x.at===j&&x.fl&&foes.includes(x.o)&&x.u.length).reduce((s,x)=>s+grArmyVal(x),0);let sc=-d*6+(P[j].ck?16:0);
        if(en>0){if(en*1.15<val)sc+=40+en/400;else continue;}
        for(const k of P[j].adj)if(P[k].land&&foes.includes(GC.prov[k].o)&&gmilHasPort(k))sc+=14+P[k].dev*3;   // blockade a foe's port
        if(sc>ts){ts=sc;tgt=j;}}fr=nx;}
    if(tgt>=0&&tgt!==a.at){const r=grPath(c,a.at,tgt,1);if(r&&r.path.length)a.path=r.path;}
    if(a.u.some(r=>r[0]==='minel')&&!a.path.length&&P[a.at].sea&&R()<.5)a.mine=1;}
  // buy ships when the navy is small next to the army
  const ports=P.filter(p=>p.land&&GC.prov[p.i].o===c&&gmilHasPort(p.i)&&gmilZoneOf(p.i)>=0);
  if(ports.length&&foes.length&&N.cash>2600){const nav=mine.reduce((s,a)=>s+grArmyVal(a),0),arm=GC.armies.filter(a=>a.o===c&&!a.fl).reduce((s,a)=>s+grArmyVal(a),0);
    if(nav<arm*.14&&!GC.mil.fq.some(q=>q.o===c)){const ks=['ship','boat','sub','fast','minel'].filter(k=>grHasKind(fac,k));const k=ks[Math.floor(R()*ks.length)];if(k)gmilBuyFleet(c,ports[Math.floor(R()*ports.length)].i,k);}}}
function gmilAIStrikes(c,R){const N=GC.nat[c],P=GCM.P,Q=gmilN(c);const foes=Object.keys(GC.war).filter(k=>k.split('|').includes(c)).map(k=>k.split('|').find(x=>x!==c)).filter(x=>GC.nat[x]&&!GC.nat[x].dead);if(!foes.length)return;
  if(GMIL_DRN.includes(c)){   // build launch sites toward the front and put a launcher truck with the biggest army that stands at one
    if(N.cash>1800&&R()<.35&&P.filter(p=>p.land&&GC.prov[p.i].o===c&&geCount(p.i,'dsite')).length<3){const cs=P.filter(p=>p.land&&GC.prov[p.i].o===c&&p.adj.some(j=>P[j].land&&foes.includes(GC.prov[j].o))).sort((a,b)=>b.dev-a.dev||a.i-b.i);for(const p of cs){if(!geBuild(c,p.i,'dsite'))break;}}
    if(N.cash>900&&R()<.3){const a=GC.armies.filter(x=>x.o===c&&!x.fl&&x.u.length&&(x.ln|0)<1).sort((x,y)=>grArmyVal(y)-grArmyVal(x)||x.id-y.id).find(x=>geEff(x.at,'dsite')>0||geEff(x.at,'factory')>0);if(a)gmilBuyLauncher(c,a.id);}}
  const xo={},xg=f=>typeof gescWarAI!=='function'?true:xo[f]!==undefined?xo[f]:(xo[f]=gescWarAI(c,f,6,R));   // escalation ladder: an AI rarely opens strategic strikes first; it answers them freely
  let tries=0;while(Q.so.length<2&&tries++<8){const types=['m','a','d'];let t=types[Math.floor(R()*3)];if(Q.dr>=8&&R()<.6)t='d';if(t==='m'&&Q.ms<=1&&R()<.7)t='a';if(t==='a'&&Q.pb<1&&R()<.6)continue;   // out of guided bombs: most raids are held back   // the last salvo is a reserve
    // target: the foe province with the best buildings in range, else a foe fleet
    let best=-1,bs=0;for(const p of P){if(!p.land||!foes.includes(GC.prov[p.i].o))continue;const bl=geBl(p.i).filter(r=>['factory','refinery','power','port','airfield','mine'].includes(r[0])&&(r[1]|0)<70).length;const s=bl*10+p.dev-(gmilN(GC.prov[p.i].o).ic>0?geCount(p.i,'aa')*8:0);if(s>bs&&gmilSites(c,p.i,GMIL_ST[t].rng,t)>=0){bs=s;best=p.i;}}
    if(best>=0&&bs>=10&&xg(GC.prov[best].o)){gmilStrike(c,t,best,'b');continue;}
    let ba=-1,bv=0;for(const p of P){if(!p.land||!foes.includes(GC.prov[p.i].o))continue;const v=GC.armies.filter(a=>a.at===p.i&&!a.fl&&foes.includes(a.o)).reduce((s,a)=>s+grArmyVal(a),0);if(v>bv&&gmilSites(c,p.i,GMIL_ST[t].rng,t)>=0){bv=v;ba=p.i;}}
    if(ba>=0&&bv>3000){gmilStrike(c,t,ba,'a');continue;}
    let bz=-1,zv=0;for(const a of GC.armies)if(a.fl&&foes.includes(a.o)&&a.u.length&&!a.path.length){const v=grArmyVal(a);if(v>zv&&gmilSites(c,a.at,GMIL_ST[t].rng,t)>=0){zv=v;bz=a.at;}}
    if(bz>=0&&zv>2500)gmilStrike(c,t,bz,'f');}}

// ---------- turn hooks ----------
function gmilPlan(){   // after grAIPlan, before movement: AI fronts / fleets / strikes, then front-assist moves for everyone
  gmilEnsure();const M=GC.mil;const R=grRng(GC.seed*61+GC.turn*11);
  for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead)continue;
    if(N.ai){try{gmilAIFronts(c);gmilAIFleets(c,R);gmilAIStock(c,R);gmilAIStrikes(c,R);}catch(e){console.error('gmilAI',c,e);}}
    else{for(const f of gmilFronts(c).slice())if(!GC.nat[f.foe]||GC.nat[f.foe].dead||!grAtWar(c,f.foe)){M.fr.splice(M.fr.indexOf(f),1);for(const a of GC.armies)if(a.fr===f.id)a.fr=0;}}}
  const plan={};for(const f of M.fr.slice().sort((x,y)=>x.id-y.id)){if(GC.nat[f.o].dead)continue;gmilPlanFront(f,plan);}}
function gmilTurnEnd(){const M=GC.mil;if(!M)return;gmilSeaStep();gmilFleetArrive();gmilGenStep(false);try{gmilDrMonth();}catch(e){console.error('gmilDrMonth',e);}
  try{gmilStockMonth();}catch(e){console.error('gmilStockMonth',e);}
  for(const a of GC.armies)if(a.fl&&a.mine&&!a.u.some(r=>r[0]==='minel'))a.mine=0;
  gmilBlockRefresh();
  for(const p of GCM.P){if(!M.bk[p.i])continue;const o=GC.prov[p.i].o;if(o===GC.me)grLog(p.n+' is under naval blockade: port income and sea trade are cut.',o);}}
function gmilHashStr(){const M=GC.mil;if(!M)return '';let s='|M';for(const id of Object.keys(M.g).sort((a,b)=>a-b)){const g=M.g[id];s+=id+':'+g.tr+g.xp+','+g.st+','+g.aid+';';}
  for(const f of M.fr)s+='F'+f.id+f.o+f.foe+f.ord;for(const k of Object.keys(M.zm).sort())s+='Z'+k+M.zm[k].o+M.zm[k].n;for(const c of Object.keys(M.n).sort())s+=c+M.n[c].ms+'d'+(M.n[c].dr|0)+'i'+(M.n[c].ic|0);for(const a of GC.armies)if(a.ln)s+='L'+a.id+a.ln;return s;}
