// RG4 elections & refugees (lane G). NO new engine: approval reads the ONE war-support meter (13v) + provincial unrest; results are GMOD rows;
// refugees are a monthly GMOD_HOOK moving unrest to peaceful neighbours. State GC.el = {nx:{code:month}, camp:{code:bonus}, ref:{code:pool}, log:[]} (saved with the campaign).
// Electoral democracies as of Nov 2026 (data row; Ukraine's elections are suspended under martial law, so it is left out on purpose).
const EL_DEM=['US','IL','GB','FR','DE','PL','IT','GR','ES','SE','JP','KR','TW','IN','AU','CA','BR','MX','AR','CO','CL','ZA','ID','PH','NG','TR','EU'];
const EL_TERM=48, EL_CAMP=300, EL_LOSE_WS=-.08, EL_WIN_INC=.03;
function elS(){if(!GC.el)GC.el={nx:{},camp:{},ref:{},log:[]};return GC.el;}
function elHash(c){let h=7;for(let i=0;i<c.length;i++)h=(h*31+c.charCodeAt(i))%9973;return h;}
function elIsDem(c){return EL_DEM.includes(c)&&GC.nat[c]&&!GC.nat[c].dead;}
function elNext(c){const S=elS();if(S.nx[c]===undefined){const r=typeof GR_REAL==='object'&&GR_REAL.el&&GR_REAL.el[c];   /* real26: the real election calendar first */
    S.nx[c]=r?Math.max(GC.turn||1,grRealTurn(r[0],r[1])):(GC.turn||0)+6+elHash(c+(GC.seed||''))%EL_TERM;}return S.nx[c];}
function elUn(c){let s=0,n=0;for(const p of GCM.P)if(p.land&&GC.prov[p.i].o===c){s+=GC.prov[p.i].un;n++;}return n?s/n:0;}
function elApproval(c){const S=elS();const ws=typeof wsOf==='function'?wsOf(c):60;return Math.max(0,Math.min(100,Math.round(ws*.6+(100-Math.min(100,elUn(c)*1.5))*.4+(S.camp[c]||0))));}
function elCampaign(c){const N=GC.nat[c],S=elS();if(!elIsDem(c))return 'No election to fight.';if(N.cash<EL_CAMP)return 'Need $'+EL_CAMP+'.';if((S.camp[c]||0)>=8)return 'The campaign is already at full strength.';N.cash-=EL_CAMP;S.camp[c]=8;return '';}
function elHold(c){const S=elS(),N=GC.nat[c],a=elApproval(c),win=a>=50;S.nx[c]=GC.turn+EL_TERM;S.camp[c]=0;
  if(win){gmodAdd({id:'el_win_'+c,src:'Election mandate',scope:'nation',stat:'income',add:EL_WIN_INC,t:c,until:GC.turn+12});}
  else{gmodAdd({id:'el_lose_'+c,src:'New government',scope:'nation',stat:'warSupport',add:EL_LOSE_WS,t:c,until:GC.turn+12});
    for(const e of gdEnemies(c))gdRel(c,e,10);
    for(const p of GCM.P)if(p.land&&GC.prov[p.i].o===c)GC.prov[p.i].un=Math.max(0,GC.prov[p.i].un-3);}
  S.log.push([GC.turn,c,a,win?1:0]);if(S.log.length>60)S.log.shift();
  grLog('Election in '+gdNatName(c)+': approval '+a+'% — '+(win?'the government is returned.':'the government falls'+(gdEnemies(c).length?' and the new cabinet seeks talks.':'.')),c);return win;}
// refugees: front-line provinces of a nation at war send people out; peaceful neighbours take them in (unrest), the origin pays in rebuilding (income)
function elRefugees(){const S=elS();
  for(const c of Object.keys(GC.nat).sort()){const N=GC.nat[c];if(N.dead)continue;const foes=gdEnemies(c);let pool=S.ref[c]||0;
    if(foes.length){let front=0;for(const p of GCM.P)if(p.land&&GC.prov[p.i].o===c)for(const j of p.adj){const q=GCM.P[j];if(q&&q.land&&foes.includes(GC.prov[j].o)){front++;break;}}pool+=Math.min(6,front);}
    pool*=.97;if(pool<.5)pool=0;pool=Math.min(100,pool);if(pool)S.ref[c]=Math.round(pool*10)/10;else delete S.ref[c];
    if(pool>=4)gmodAdd({id:'el_rebuild_'+c,src:'Refugees & rebuilding',scope:'nation',stat:'income',add:-Math.min(.1,pool/400),t:c,until:GC.turn+2});
    if(pool>=8){const cnt=new Map();for(const p of GCM.P)if(p.land&&GC.prov[p.i].o===c)for(const j of p.adj){const q=GCM.P[j];if(q&&q.land){const o=GC.prov[j].o;if(o!==c&&GC.nat[o]&&!GC.nat[o].dead&&!gdEnemies(o).length)cnt.set(j,o);}}
      for(const [j] of [...cnt].sort((a,b)=>a[0]-b[0]))GC.prov[j].un=Math.min(100,GC.prov[j].un+Math.min(2,pool/20));}}}
function elMonth(){if(!GC||!GC.nat)return;const S=elS();elRefugees();
  for(const c of Object.keys(GC.nat).sort()){if(!elIsDem(c))continue;if(GC.turn>=elNext(c))elHold(c);}}
GMOD_HOOKS.push(elMonth);
alAdd('elect','🗳','Election',c=>{if(!elIsDem(c))return null;const m=elNext(c)-GC.turn;return m<=6?{n:Math.max(0,m),tip:'Election in '+Math.max(0,m)+' months — approval '+elApproval(c)+'%. Campaign in the Elections tab.',go:()=>npOpen(c,'elect')}:null;});
npTab('elect','🗳','Elections & refugees',(code,body,c)=>{const S=elS(),own=c.own&&code===GC.me;
  let h='';if(elIsDem(code)){const a=elApproval(code),m=Math.max(0,elNext(code)-GC.turn),col=a>=50?'#7fd48a':'#ff9d8e';
    h+='<div style="font-size:24px"><b style="color:'+col+'">Approval '+a+'%</b></div><div style="opacity:.85;margin:6px 0">Voters judge war support and unrest at home. Election in '+m+' months; at 50% or more the government is returned (+3% income for a year); below it a new cabinet takes over (war support -8% for a year, and it reaches out to enemies).'+((S.camp[code]||0)?' <b>Campaign running (+'+S.camp[code]+').</b>':'')+'</div>';}
  else h+='<div style="opacity:.85;margin:6px 0">This nation holds no competitive elections; its stability rests on war support and unrest instead.</div>';
  const pool=S.ref[code]||0;h+='<div style="margin:8px 0"><b>Refugees from the fighting: '+Math.round(pool)+'</b>'+(pool>=4?' — rebuilding costs reduce income.':'')+(pool>=8?' Neighboring provinces are taking people in and feel the strain.':'')+'</div>';
  const nb=Object.keys(S.ref).filter(o=>o!==code&&S.ref[o]>=8&&GCM&&gevNb(code).includes(o));if(nb.length)h+='<div style="margin:8px 0;color:#ffe6a8">Refugees are arriving from '+nb.map(gdNatName).join(', ')+' (unrest on the border).</div>';
  body.innerHTML=h;if(own&&elIsDem(code)){const msg=document.createElement('div');msg.style.cssText='margin:8px 0;color:#ffe6a8';body.appendChild(msg);const b=document.createElement('button');b.textContent='Campaign ($'+EL_CAMP+')';b.title='+8 approval at the next election';b.style.cssText='font-size:15px;padding:4px 12px;cursor:pointer';b.onclick=()=>{const x=elCampaign(code);if(x)msg.textContent=x;else npDraw();};body.appendChild(b);}});
// 13zx-gtv.js — Lane G RG5: TV news broadcasts. Presentation only: a lower-third "broadcast" card after the turn for the
// biggest story of the month. Fed by GC.log (the one event engine writes there through grLog: world events, war, capitals,
// peace, revolts, pacts). Nothing is saved. Fictional channels and fictional anchors only — no real networks or people.
const GTV_CH=[{n:'Meridian 24',c:'#b8322a'},{n:'Global Eye',c:'#1f6fb2'},{n:'Horizon News',c:'#2e8b57'},{n:'Continental Wire',c:'#6f4fa0'},{n:'Northstar TV',c:'#c27a12'}];
const GTV_AN=['Mara Lind','Tomas Verhoeven','Ines Kalder','Samir Dorn','Yuki Tanabe','Ada Okafor','Lukas Brandt','Priya Venkat'];
const GTV_BIG=/declared war|capital|eliminated|peace|nuclear|coup|revolt|captured|WORLD:|pact|alliance|guarantee/i;
const GTV_HOT=/declared war|capital|eliminated|nuclear|coup/i;
let GTV_LAST=-1;
// the month's biggest story: world events weigh most, then our own nation's news, then anything hot (war, capitals, nukes)
function gtvPick(){if(!GC||!GC.log)return null;const T=GC.turn-1;let best=null,bw=-1;
  for(const l of GC.log){if(l[0]!==T||!(l[2]===''||GTV_BIG.test(l[1])))continue;
    const w=(l[2]===''?3:0)+(l[2]===GC.me?4:0)+(GTV_HOT.test(l[1])?5:0)+(/WORLD:/.test(l[1])?2:0);if(w>bw){bw=w;best=l;}}
  return best;}
function gtvShow(){if(!GC||!GC.me||GTV_LAST===GC.turn)return;const b=gtvPick();if(!b)return;GTV_LAST=GC.turn;
  const host=document.getElementById('gMapWrap');if(!host)return;let old=document.getElementById('gTV');if(old)old.remove();
  const seed=GC.seed|0,ch=GTV_CH[(seed+GC.turn)%GTV_CH.length],an=GTV_AN[(seed*7+GC.turn*3)%GTV_AN.length];
  const hot=GTV_HOT.test(b[1]);const d=document.createElement('div');d.id='gTV';
  d.style.cssText='position:absolute;left:0;right:0;bottom:0;display:flex;align-items:stretch;height:66px;background:rgba(14,18,26,.94);border-top:3px solid '+ch.c+';box-shadow:0 -6px 18px rgba(0,0,0,.45);color:#f4f1ea;font:15px system-ui,sans-serif;z-index:6;cursor:pointer;transform:translateY(20px);opacity:0;transition:opacity .4s,transform .4s';
  const tag=document.createElement('div');tag.style.cssText='background:'+ch.c+';color:#fff;min-width:150px;display:flex;flex-direction:column;justify-content:center;padding:0 14px;font-weight:700;letter-spacing:.5px';
  const live=document.createElement('span');live.textContent=(hot?'BREAKING':'LIVE')+' ● ';live.style.cssText='font-size:11px;opacity:.9';
  const cn=document.createElement('span');cn.textContent=ch.n;cn.style.cssText='font-size:15px';tag.appendChild(live);tag.appendChild(cn);
  const body=document.createElement('div');body.style.cssText='flex:1;display:flex;flex-direction:column;justify-content:center;padding:4px 16px;min-width:0';
  const hd=document.createElement('div');hd.textContent=b[1].replace(/\.$/,'');hd.style.cssText='font-size:17px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
  const sub=document.createElement('div');sub.textContent='Anchor '+an+' · '+grMonStr(GC.turn-1);sub.style.cssText='font-size:11px;opacity:.65;margin-top:2px;letter-spacing:.3px';
  body.appendChild(hd);body.appendChild(sub);d.appendChild(tag);d.appendChild(body);host.appendChild(d);
  d.onclick=()=>d.remove();
  requestAnimationFrame(()=>{d.style.opacity='1';d.style.transform='translateY(0)';});
  setTimeout(()=>{if(!d.isConnected)return;d.style.opacity='0';d.style.transform='translateY(20px)';setTimeout(()=>d.remove(),450);},9000);}
// CEASEFIRES THAT CAN BREAK (lane G, RG20, first cut). Every truce in force (GC.tr, from peace deals and the UN) can be violated:
// each month a seeded roll per truce (4%; 2% when a third nation guarantees one side, GC.gu) brings a shooting incident:
// opinion -5, and one incident in three collapses the truce back into war. Neutral wording; no real places or people.
// Deterministic from seed + turn (multiplayer safe). UN peacekeepers / guarantees are the counter-play (they halve the odds).
function gcfTurn(){if(!GC||!GC.tr||!GC.nat)return;const R=grRng((GC.seed|0)*449+GC.turn*7);
  for(const k of Object.keys(GC.tr).sort()){if(!(GC.tr[k]>GC.turn))continue;const [a,b]=k.split('|');
    if(!GC.nat[a]||!GC.nat[b]||GC.nat[a].dead||GC.nat[b].dead)continue;
    const r=R(),r2=R();const guar=(GC.gu||[]).some(g=>(g[1]===a||g[1]===b)&&g[0]!==a&&g[0]!==b);
    if(r>(guar?.02:.04))continue;
    gdRel(a,b,-5);
    if(r2<.33){delete GC.tr[k];GC.war[k]=1;GC.wsT=GC.wsT||{};GC.wsT[k]=GC.turn;
      grLog('The ceasefire between '+gdNatName(a)+' and '+gdNatName(b)+' has collapsed after a shooting incident on the line.',a);}
    else grLog('Ceasefire violation between '+gdNatName(a)+' and '+gdNatName(b)+'. Both sides blame each other.',a);}}
// A5b NAMED BATTLES (laneA 2026-11-07): a clash of big armies becomes a legend. Rows in the ONE modifier engine (13k), no second system.
// Chain: who reacts = the winner's people (war support up, army max morale up), the loser's nation remembers (smaller "never again" rally);
// second order = war support feeds recruits/income/peace pressure (13v), army morale feeds Fight-it starts (13b gmMorMax);
// counter-play = take the province back or win a bigger battle (the legend row is per battle, expires); cost = needs a real battle (both
// sides >= 3000 army value and the weaker >= 30% of the stronger), 1 legend per province per year, so no cheap farming.
// Style flavour (name only, EQUAL value for all four styles): Zealous martyr shrine · Professional regimental honours ·
// Home defenders "never again" site · Firepower-reliant victory monument.
const GLEG_NAME={zeal:'Martyrs’ shrine',prof:'Regimental honors',home:'“Never again” memorial',fire:'Victory monument'};
const GLEG_MIN=3000,GLEG_RATIO=.3,GLEG_MONTHS=12;
function glStyle(c){try{return MORALE_STYLE[grNat(c).fac]||MORALE_STYLE[c]||'home';}catch(e){return 'home';}}
function glSide(ids){let v=0;for(const a of GC.armies)if(ids.includes(a.id))v+=grArmyVal(a);return v;}
// call BEFORE the battle is settled (armies still at full strength). Returns the legend or null.
function glBattle(b,win){if(!GC||!b)return null;const va=glSide(b.att||[]),vd=glSide(b.def||[]),hi=Math.max(va,vd),lo=Math.min(va,vd);
  if(hi+lo<GLEG_MIN*2||lo<hi*GLEG_RATIO)return null;
  if(!GC.leg)GC.leg=[];if(GC.leg.some(l=>l.p===b.p&&GC.turn-l.t<12))return null;
  const w=win==='att'?b.an:b.dn,l=win==='att'?b.dn:b.an;if(!w||!l)return null;
  const pn=GCM.P[b.p]?GCM.P[b.p].n:'?',st=glStyle(w),nm='Battle of '+pn,until=GC.turn+GLEG_MONTHS;
  GC.leg.push({p:b.p,t:GC.turn,w,l,nm,st});if(GC.leg.length>60)GC.leg.shift();
  gmodAdd({id:'leg_w_'+b.p+'_'+GC.turn,src:nm+' — '+GLEG_NAME[st],scope:'nation',stat:'warSupport',add:.04,t:w,until});
  gmodAdd({id:'leg_a_'+b.p+'_'+GC.turn,src:nm+' — '+GLEG_NAME[st],scope:'nation',stat:'armyMor',add:2,t:w,until});
  gmodAdd({id:'leg_l_'+b.p+'_'+GC.turn,src:nm+' — rally to avenge it',scope:'nation',stat:'warSupport',add:.02,t:l,until:GC.turn+6});
  try{grLog(nm+': '+(grNat(w).n||w)+' win a battle that will be remembered — '+GLEG_NAME[st].toLowerCase()+' raised.',w);}catch(e){}
  return GC.leg[GC.leg.length-1];}
function glMor(o){try{return Math.round(gmod('nation',o,'armyMor',0));}catch(e){return 0;}}
if(typeof GMOD_STATS==='object')GMOD_STATS.armyMor='Army max morale';
// 13zz-gnuke.js — Lane G RG10 (first cut): NUCLEAR PROGRAMMES and the grand-map nuclear strike. Grand map only, never in battles.
// Nuclear powers start with a few warheads (GNK.start). Anyone else (and Iran, part-way) can start a programme: enrichment → test-ready →
// a test (world opinion drops, the first warhead appears) → one more warhead a year (max GNK.cap). Warheads cost upkeep every month.
// A strike (two-step confirm, human) or a last-resort AI strike wrecks one enemy province: its buildings and garrison are destroyed,
// armies there are lost, unrest and fallout last 3 years, the world's opinion of the launcher collapses, the victim proposes sanctions
// (UN, RG2), the launcher's war support splits, and a nuclear victim (AI) strikes back at the launcher's capital.
// Effects are GMOD rows + relations + the event log (grLog) — no separate battle code. State: GC.nuk (saved with the campaign).
// Neutral: no real places' casualty figures, no real leaders. Equal rules for every nation.
const GNK={start:{US:3,RU:3,CN:2,GB:1,FR:1,IN:1,PK:1,KP:1,IL:1},pre:{IR:2},
  names:['No program','Enrichment','Test-ready','Warhead (tested)'],months:[0,6,6,0],
  cost:1500,upkeep:150,cap:6,fallout:36,strikeCost:0,aiGap:24,flight:0};   // real ICBMs/IRBMs land in ~10-30 minutes: impact is immediate on the map; the target gets a launch-detected alert (Abdullah 2026-11-07 10:22 "Not realistic" about a month-long flight)
function gnkN(c){if(!GC.nuk)GC.nuk={n:{},fo:{},pend:[]};const S=GC.nuk;if(!S.n[c]){const w=GNK.start[c]||0;S.n[c]={st:w?3:(GNK.pre[c]||0),p:0,w:w,last:-99};}return S.n[c];}
function gnkName(c){return typeof gdNatName==='function'?gdNatName(c):c;}
function gnkStart(c){const N=gnkN(c),A=GC.nat[c];if(N.st!==0)return 'The program is already running.';if(A.cash<GNK.cost)return 'Costs $'+GNK.cost+'.';
  A.cash-=GNK.cost;N.st=1;N.p=0;grLog(gnkName(c)+' starts a nuclear program.',c);return '';}
// RG10 follow-on: the programme's site is the capital's province. While an enemy army holds it, enrichment/test work stalls
// (the work is seized or buried; no progress that month). Logged once when the occupation starts and once when it ends.
function gnkOccupied(c,N){const A=GC.nat[c],cap=A&&A.cap;const occ=cap>=0&&GC.prov[cap]&&GC.prov[cap].o!==c&&grAtWar(c,GC.prov[cap].o)&&GC.armies.some(a=>a.at===cap&&!a.fl&&grAtWar(a.o,c));
  if(occ&&!N.occ){N.occ=1;grLog(gnkName(c)+': the program site is under occupation. Work has stopped.',c);}
  else if(!occ&&N.occ){N.occ=0;grLog(gnkName(c)+': the program site is back under national control.',c);}
  return !!occ;}
// one month: programme stages, tests, warhead growth, upkeep, fallout, AI decisions
function gnkMonth(){if(!GC||!GC.nat)return;if(GC.nuk&&GC.nuk.pend&&GC.nuk.pend.length){const due=GC.nuk.pend.filter(x=>x[2]<=GC.turn);GC.nuk.pend=GC.nuk.pend.filter(x=>x[2]>GC.turn);for(const x of due)gnkImpact(x[0],x[1],x[3]);}
  const alive=Object.keys(GC.nat).filter(c=>!GC.nat[c].dead).sort();
  const R=grRng((GC.seed|0)*311+GC.turn*17);
  for(const c of alive){const N=gnkN(c),A=GC.nat[c];
    if(N.st>=1&&N.st<=2){if(!gnkOccupied(c,N))N.p++;if(N.p>=GNK.months[N.st]){N.st++;N.p=0;if(N.st===3){N.w++;grLog('Nuclear test: '+gnkName(c)+' has tested a device.','');
        for(const o of alive)if(o!==c)gdRel(o,c,-12);}}}
    else if(N.st===3){N.p++;if(N.p%12===0&&N.w<GNK.cap){N.w++;}}
    if(N.w>0)A.cash-=Math.min(Math.max(0,A.cash),N.w*GNK.upkeep);   /* upkeep never pushes the treasury below zero (it drains what is there) */
    // a programme is seen: the world grows wary of it (slow, every month until it becomes a warhead)
    if(N.st>=1&&N.st<3)for(const o of alive)if(o!==c)gdRel(o,c,-1);
    // AI nations at war with a nuclear power may start their own programme (cascade); rare and seeded
    if(!A.ai)continue;
    if(N.st===0&&A.cash>2500&&alive.some(o=>o!==c&&GC.nat[o]&&(gnkN(o).w>0)&&grAtWar(c,o))&&R()<.03){N.st=1;N.p=0;grLog(gnkName(c)+' is reported to be starting a nuclear program.',c);}
    // last resort: the capital is held by an enemy army and the nation has warheads → strike the occupied capital
    if(N.w>0&&N.st===3&&GC.turn-N.last>=GNK.aiGap){const cap=A.cap;if(cap>=0&&GC.prov[cap]&&GC.prov[cap].o!==c&&grAtWar(c,GC.prov[cap].o)&&GC.armies.some(a=>a.at===cap&&!a.fl&&grAtWar(a.o,c))){const oc=GC.prov[cap].o;if(typeof gescWarOf!=='function'||gescWarOf(c,oc)>=7)gnkLaunch(c,cap,true);else gescNAlert(c,oc,1);}}   /* escalation ladder: a month on nuclear alert comes first, so the occupier can leave or make peace */
  }
  for(const pi of Object.keys(GC.nuk.fo))if(GC.nuk.fo[pi]<GC.turn)delete GC.nuk.fo[pi];else if(GC.prov[pi])GC.prov[pi].un=Math.min(100,(GC.prov[pi].un||0)+3);
}
// the strike. pi must be an enemy land province of a nation at war with the launcher. ai: no confirm needed (its own decision)
function gnkLaunch(c,pi,ai,noRet){const N=gnkN(c),p=GCM.P[pi];if(!p||!p.land)return 'Not a land province.';const o=GC.prov[pi].o;
  if(N.w<1)return 'No warheads.';if(o===c||!grAtWar(c,o))return 'Only enemy provinces at war with you.';
  N.w--;N.last=GC.turn;GC.nuk.pend=GC.nuk.pend||[];if(GNK.flight>0)GC.nuk.pend.push([c,pi,GC.turn+GNK.flight,noRet?1:0,o]);   /* travel time: the warhead lands GNK.flight months later */
  grLog('Launch detected: nuclear warheads fired at '+p.n+' ('+gnkName(o)+'). Impact within minutes.',c);
  if(o===GC.me||c===GC.me)try{gevToast(['☢ Launch detected — warheads hit '+p.n+' within minutes']);}catch(x){}
  if(!(GNK.flight>0))gnkImpact(c,pi,noRet?1:0);
  return '';}
// impact (a month after launch): the province is hit unless the front has moved since the launch
function gnkImpact(c,pi,noRet){const p=GCM.P[pi],o=GC.prov[pi].o;
  if(o===c||!grAtWar(c,o)){grLog('The warheads over '+p.n+' are called back: the front has changed.',c);return;}
  const st=GC.prov[pi];st.un=Math.min(100,(st.un||0)+45);st.gar=[];
  for(const b of gmBuildings(pi))b[1]=100;                      /* every building in the province is destroyed (damage 100) */
  GC.armies=GC.armies.filter(a=>!(a.at===pi&&!a.fl));          /* armies in the province are lost */
  GC.nuk.fo[pi]=GC.turn+GNK.fallout;
  for(const x of Object.keys(GC.nat)){if(GC.nat[x].dead||x===c)continue;gdRel(x,c,grAllied(x,c)?-35:-22);}
  gmodAdd({id:'nuk_ws_'+c,src:'Nuclear strike',scope:'nation',stat:'warSupport',add:-.15,t:c,until:GC.turn+12});
  grLog('Nuclear strike on '+p.n+' by '+gnkName(c)+'. Fallout covers the province.',c);
  try{unPropose(o,'sanction',c,true);}catch(e){}
  if(!noRet&&gnkN(o).w>0&&grAtWar(o,c)){   /* a nuclear victim answers: an AI victim strikes the launcher's capital at once; a human gets a log line */
    if(GC.nat[o].ai&&GC.nat[c].cap>=0)gnkLaunch(o,GC.nat[c].cap,true,true);
    else grLog(gnkName(o)+' could answer with its own warheads.',o);}
  return '';}
// the picker: enemy land provinces next to our land, capitals first (up to 8)
function gnkTargets(c){const P=GCM.P,out=[],seen=new Set();const foes=new Set(gdEnemies(c));
  for(const f of foes){const cap=GC.nat[f].cap;if(cap>=0&&!seen.has(cap)){seen.add(cap);out.push(cap);}}
  for(const p of P){if(!p.land||!foes.has(GC.prov[p.i].o))continue;if(seen.has(p.i))continue;if(p.adj.some(j=>P[j]&&P[j].land&&GC.prov[j].o===c)){seen.add(p.i);out.push(p.i);}}
  return out.slice(0,8);}
function gnkPickTarget(c){const N=gnkN(c);if(N.w<1)return;const ts=gnkTargets(c);if(!ts.length){guModal('<h2 style="margin:0 0 8px;font-size:20px">☢ Launch</h2><div>No enemy province is within reach of our front.</div>',[['Close',()=>{}]]);return;}
  const bs=ts.map(pi=>[GCM.P[pi].n+' ('+(GC.nat[GC.prov[pi].o]&&GC.nat[GC.prov[pi].o].cap===pi?'capital':gnkName(GC.prov[pi].o))+')',()=>gnkConfirm(c,pi)]);bs.push(['Back',()=>npOpen(c,'nuke')]);
  guModal('<h2 style="margin:0 0 8px;font-size:20px">☢ Choose a target</h2><div style="opacity:.8;margin-bottom:6px">Enemy provinces in reach. The next screen asks you to confirm.</div>',bs);}
function gnkConfirm(c,pi){const o=GC.prov[pi].o;
  guModal('<h2 style="margin:0 0 8px;font-size:20px">Launch on '+GCM.P[pi].n+'?</h2><div style="line-height:1.5">Warheads hit within minutes; early-warning radars see the launch, so the target and the world know who fired. On impact they destroy the buildings and garrison there, kill armies in the province and leave fallout for three years. Sanctions follow, the world rounds on '+gnkName(c)+', and '+gnkName(o)+' may answer with its own warheads.</div>',
    [['Launch',()=>{const e=gnkLaunch(c,pi,false);if(e)grLog(e,c);try{guTop();grandMapRefresh();}catch(x){}npOpen(c,'nuke');},1],['Back',()=>gnkPickTarget(c)]]);}
// the nation-panel tab: stage, warheads, actions (own nation only); small menu buttons
function gnkRow(label,val){return '<div style="display:flex;justify-content:space-between;gap:24px;padding:3px 0;border-bottom:1px solid #26384a"><span style="opacity:.75">'+label+'</span><b>'+val+'</b></div>';}
function gnkBtn(label,fn){const b=document.createElement('button');b.textContent=label;b.style.cssText='font:15px system-ui,sans-serif;padding:6px 14px;margin:6px 8px 0 0;background:#1e3347;color:#e8f0f7;border:1px solid #4a6a88;border-radius:5px;cursor:pointer';b.onclick=fn;return b;}
if(typeof npTab==='function')npTab('nuke','☢','Nuclear',(code,body,c)=>{const own=code===GC.me,N=gnkN(code),A=GC.nat[code];
  const stage=GNK.names[N.st]||'';const nextM=N.st>=1&&N.st<=2?' (next stage in '+Math.max(0,GNK.months[N.st]-N.p)+' months)':'';
  body.innerHTML='<div style="font-size:17px;margin-bottom:6px"><b>Nuclear status</b></div><div style="max-width:520px">'
   +gnkRow('Program',stage+nextM)+gnkRow('Warheads',N.w)+gnkRow('Upkeep per month',N.w||N.st>=1?'$'+(N.w*GNK.upkeep):'—')
   +gnkRow('Fallout zones',Object.keys(GC.nuk.fo).length)+'</div>'
   +'<div style="margin-top:10px;opacity:.8;max-width:520px">Every nuclear power pays upkeep for its warheads. A strike brings sanctions, world anger and fallout; a nuclear victim can answer. AI nations use a strike only as a last resort.</div>';
  if(own){const row=document.createElement('div');body.appendChild(row);
    if(N.st===0)row.appendChild(gnkBtn('Start a nuclear program ($'+GNK.cost+')',()=>{const e=gnkStart(code);if(e)grLog(e,code);npOpen(code,'nuke');}));
    if(N.w>0&&N.st>=0)row.appendChild(gnkBtn('Launch a strike…',()=>gnkPickTarget(code)));}
});
GMOD_HOOKS.push(gnkMonth);
alAdd('nukein','☢','Inbound',c=>{if(!c||!GC.nuk||!GC.nuk.pend)return null;const n=GC.nuk.pend.filter(x=>x[4]===c).length;return n?{n,tip:'Nuclear warheads are inbound on one of your provinces',go:()=>npOpen(c,'nuke')}:null;});
// real26 (Abdullah 2026-11-07 20:20 "start from the world as it really is"): the REAL dated events of the next 24 months, as rows in the ONE
